        T *h_df_du;
        T *h_dtau_dfext;
        T *h_dqdd_dfext;
        T *h_f_ext_gradient_dq;  // -dJ^T/dq, nv*6NB*nv (both base modes)
        T *h_Y;
        T *h_dqdd_dpi;
        T *h_ke_regressor;
        T *h_pe_regressor;
        T *h_coriolis;
        T *h_dccrba;
        T *h_cmm_time_variation;
        T *h_end_effector_pose;
        T *h_end_effector_pose_gradient;
        T *h_end_effector_pose_hessian;
        T *h_frame_jacobian;
        T *h_frame_jacobian_dot;
        T *h_osc_inertia;
        T *h_eePose;
        T *h_eePoseGrad;
        T *h_idsva_so;
        T *h_df2;
        T *h_x_kp1;
        T *h_dAB;
