     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_gradient_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                             const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose_gradient requires all-data or kinematics gridData");
        int stride_q = USE_COMPRESSED_MEM ? NUM_JOINTS: 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose_gradient", END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        if (USE_COMPRESSED_MEM) {end_effector_pose_gradient_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_gradient_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_end_l2_persisting(0));}
    }

    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Closed-form analytic d2(pose)/dv2; matches RBDReference.end_effector_pose_hessian_analytic (which agrees with pinocchio getJointKinematicHessian(LOCAL_WORLD_ALIGNED) to the FD floor fleet-wide; CUDA confirmed on iiwa14-fixed + go2-floating).
     *   Inner-owns scratch placement: the large nv^2 output s_end_effector_pose_hessian moves to d_workspace when !OUT_IN_SMEM. The s_Xworld+s_Sworld+s_E_sc scratch in s_temp stays in smem at every tier.
     *
     * @param s_end_effector_pose_hessian is a pointer to memory of size 6*NUM_VEL*NUM_VEL*NUM_EE where NUM_VEL = 7 and NUM_EE = 1 (d^2(pose)/dv^2 tangent-space Hessian, pinocchio convention)
     * @param s_end_effector_pose_gradient is a pointer to memory of size 6*NUM_VEL*NUM_EE (the d/dv tangent Jacobian at q)
     * @param s_q is the vector of joint positions (size NUM_POS = 7; kept for signature compatibility, unused by the analytic path)
     * @param s_Xhom is the per-joint LOCAL homogeneous-transform buffer (read-only)
     * @param s_temp is helper shared memory of size 260 (s_Xworld | s_Sworld | s_E_sc; always kept in smem)
     * @param d_workspace is the global spill arena s_end_effector_pose_hessian is repointed at when !OUT_IN_SMEM (else unused)
     * @param d_robotModel is the model-specific helper struct (kept for signature compatibility, unused by the analytic path)
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_linalg_smem is optional byte-addressed shared memory (reserved; unused by this inner)
     */
    template <typename T, bool OUT_IN_SMEM = true>
    __device__
    void end_effector_pose_hessian_inner(T *s_end_effector_pose_hessian, T *s_end_effector_pose_gradient, const T *s_q, T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, const robotModel<T> *d_robotModel, unsigned char *s_linalg_smem) {
        if constexpr (!OUT_IN_SMEM) { s_end_effector_pose_hessian = d_workspace; } else { (void)d_workspace; }
        (void)s_q; (void)d_robotModel; (void)s_linalg_smem;
        // scratch in s_temp: s_Xworld (16*n_joints) | s_Sworld (16*nv*num_ees) | s_E_sc (4*num_ees)
        T *s_Xworld = &s_temp[0];
        T *s_Sworld = &s_temp[144];  // per-DOF world-frame 4x4 generator (S_i_world)
        T *s_E_sc   = &s_temp[256];  // cy, sy, cp, sp per ee
        //
        // Step 1: forward kinematics -- build s_Xworld[16*j] for every joint via BFS-level chain-up
        //
        // BFS level 0 -> joints [0]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 0; par = -1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 1 -> joints [1]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 1; par = 0; }
