            static const int s_d2ee_cross_tab[252] = {0, 16, 0, 16, 96, 1, 0, 32, 0, 32, 96, 2, 0, 48, 0, 48, 96, 3, 0, 64, 0, 64, 96, 4, 0, 80, 0, 80, 96, 5, 0, 96, 0, 96, 96, 6, 0, 16, 16, 0, 96, 7, 16, 32, 16, 32, 96, 9, 16, 48, 16, 48, 96, 10, 16, 64, 16, 64, 96, 11, 16, 80, 16, 80, 96, 12, 16, 96, 16, 96, 96, 13, 0, 32, 32, 0, 96, 14, 16, 32, 32, 16, 96, 15, 32, 48, 32, 48, 96, 17, 32, 64, 32, 64, 96, 18, 32, 80, 32, 80, 96, 19, 32, 96, 32, 96, 96, 20, 0, 48, 48, 0, 96, 21, 16, 48, 48, 16, 96, 22, 32, 48, 48, 32, 96, 23, 48, 64, 48, 64, 96, 25, 48, 80, 48, 80, 96, 26, 48, 96, 48, 96, 96, 27, 0, 64, 64, 0, 96, 28, 16, 64, 64, 16, 96, 29, 32, 64, 64, 32, 96, 30, 48, 64, 64, 48, 96, 31, 64, 80, 64, 80, 96, 33, 64, 96, 64, 96, 96, 34, 0, 80, 80, 0, 96, 35, 16, 80, 80, 16, 96, 36, 32, 80, 80, 32, 96, 37, 48, 80, 80, 48, 96, 38, 64, 80, 80, 64, 96, 39, 80, 96, 80, 96, 96, 41, 0, 96, 96, 0, 96, 42, 16, 96, 96, 16, 96, 43, 32, 96, 96, 32, 96, 44, 48, 96, 96, 48, 96, 45, 64, 96, 96, 64, 96, 46, 80, 96, 96, 80, 96, 47};
            if (d2m_cell < 42) {
