                T D20 = s_Sworld[dist_base + 2];
                T D01 = s_Sworld[dist_base + 4];
                T D11 = s_Sworld[dist_base + 5];
                T D21 = s_Sworld[dist_base + 6];
                T D02 = s_Sworld[dist_base + 8];
                T D12 = s_Sworld[dist_base + 9];
                T D22 = s_Sworld[dist_base + 10];
                T D03 = s_Sworld[dist_base + 12];
                T D13 = s_Sworld[dist_base + 13];
                T D23 = s_Sworld[dist_base + 14];
                // M = S_prox * S_dist (top 3 rows, all 4 cols)
                T M00 = P00*D00 + P01*D10 + P02*D20;
                T M01 = P00*D01 + P01*D11 + P02*D21;
                T M02 = P00*D02 + P01*D12 + P02*D22;
                T M03 = P00*D03 + P01*D13 + P02*D23;
                T M10 = P10*D00 + P11*D10 + P12*D20;
                T M11 = P10*D01 + P11*D11 + P12*D21;
                T M12 = P10*D02 + P11*D12 + P12*D22;
                T M13 = P10*D03 + P11*D13 + P12*D23;
                T M20 = P20*D00 + P21*D10 + P22*D20;
                T M21 = P20*D01 + P21*D11 + P22*D21;
                T M22 = P20*D02 + P21*D12 + P22*D22;
                T M23 = P20*D03 + P21*D13 + P22*D23;
                // H_xyz[:, vi, vj] = (S_prox*S_dist*X_ee)[:3, 3] = M[:3,:3] * p_ee + M[:3, 3]
                T Hxyz_x = M00*pex + M01*pey + M02*pez + M03;
                T Hxyz_y = M10*pex + M11*pey + M12*pez + M13;
