                T aw_1 = s_Xworld[73] * static_cast<T>(1);
                T aw_2 = s_Xworld[74] * static_cast<T>(1);
                T bw_0 = s_Xworld[72] * static_cast<T>(1);
                T bw_1 = s_Xworld[73] * static_cast<T>(1);
                T bw_2 = s_Xworld[74] * static_cast<T>(1);
                T alw_0 = static_cast<T>(0);
                T alw_1 = static_cast<T>(0);
                T alw_2 = static_cast<T>(0);
                T blw_0 = static_cast<T>(0);
                T blw_1 = static_cast<T>(0);
                T blw_2 = static_cast<T>(0);
                T pax = s_Xworld[76];
                T pay = s_Xworld[77];
                T paz = s_Xworld[78];
                // Br_world = 0.5 * ([aw]_x [bw]_x + [bw]_x [aw]_x)
                //   = 0.5 * (aw bw^T + bw aw^T) - (aw . bw) I
                T adotb = aw_0*bw_0 + aw_1*bw_1 + aw_2*bw_2;
                T Br_00 = static_cast<T>(0.5) * (aw_0*bw_0 + bw_0*aw_0) - adotb;
                T Br_01 = static_cast<T>(0.5) * (aw_0*bw_1 + bw_0*aw_1);
                T Br_02 = static_cast<T>(0.5) * (aw_0*bw_2 + bw_0*aw_2);
                T Br_10 = static_cast<T>(0.5) * (aw_1*bw_0 + bw_1*aw_0);
                T Br_11 = static_cast<T>(0.5) * (aw_1*bw_1 + bw_1*aw_1) - adotb;
                T Br_12 = static_cast<T>(0.5) * (aw_1*bw_2 + bw_1*aw_2);
                T Br_20 = static_cast<T>(0.5) * (aw_2*bw_0 + bw_2*aw_0);
                T Br_21 = static_cast<T>(0.5) * (aw_2*bw_1 + bw_2*aw_1);
                T Br_22 = static_cast<T>(0.5) * (aw_2*bw_2 + bw_2*aw_2) - adotb;
                T Bt_0 = -(Br_00*pax + Br_01*pay + Br_02*paz);
                T Bt_1 = -(Br_10*pax + Br_11*pay + Br_12*paz);
                T Bt_2 = -(Br_20*pax + Br_21*pay + Br_22*paz);
                T Hxyz_x = Br_00*pex + Br_01*pey + Br_02*pez + Bt_0;
                T Hxyz_y = Br_10*pex + Br_11*pey + Br_12*pez + Bt_1;
                T Hxyz_z = Br_20*pex + Br_21*pey + Br_22*pez + Bt_2;
                // Read [Jw_i]_x and [Jw_j]_x for the H_w correction
                T Si00 = s_Sworld[64];
                T Si10 = s_Sworld[65];
                T Si20 = s_Sworld[66];
                T Si01 = s_Sworld[68];
                T Si11 = s_Sworld[69];
                T Si21 = s_Sworld[70];
                T Si02 = s_Sworld[72];
                T Si12 = s_Sworld[73];
                T Si22 = s_Sworld[74];
                T Sj00 = s_Sworld[64];
                T Sj10 = s_Sworld[65];
                T Sj20 = s_Sworld[66];
                T Sj01 = s_Sworld[68];
                T Sj11 = s_Sworld[69];
                T Sj21 = s_Sworld[70];
                T Sj02 = s_Sworld[72];
                T Sj12 = s_Sworld[73];
                T Sj22 = s_Sworld[74];
                T SiSj00 = Si00*Sj00 + Si01*Sj10 + Si02*Sj20;
                T SiSj01 = Si00*Sj01 + Si01*Sj11 + Si02*Sj21;
                T SiSj02 = Si00*Sj02 + Si01*Sj12 + Si02*Sj22;
                T SiSj10 = Si10*Sj00 + Si11*Sj10 + Si12*Sj20;
                T SiSj11 = Si10*Sj01 + Si11*Sj11 + Si12*Sj21;
                T SiSj12 = Si10*Sj02 + Si11*Sj12 + Si12*Sj22;
                T SiSj20 = Si20*Sj00 + Si21*Sj10 + Si22*Sj20;
                T SiSj21 = Si20*Sj01 + Si21*Sj11 + Si22*Sj21;
                T SiSj22 = Si20*Sj02 + Si21*Sj12 + Si22*Sj22;
                T HW_x = static_cast<T>(0.5) * ((Br_21 - SiSj21) - (Br_12 - SiSj12));
                T HW_y = static_cast<T>(0.5) * ((Br_02 - SiSj02) - (Br_20 - SiSj20));
                T HW_z = static_cast<T>(0.5) * ((Br_10 - SiSj10) - (Br_01 - SiSj01));
                s_end_effector_pose_hessian[(0 + 32) + 0 * 49] = Hxyz_x;
                s_end_effector_pose_hessian[(0 + 32) + 1 * 49] = Hxyz_y;
                s_end_effector_pose_hessian[(0 + 32) + 2 * 49] = Hxyz_z;
                s_end_effector_pose_hessian[(0 + 32) + 3 * 49] = HW_x;
                s_end_effector_pose_hessian[(0 + 32) + 4 * 49] = HW_y;
                s_end_effector_pose_hessian[(0 + 32) + 5 * 49] = HW_z;
            }
            // ee=0 pair (vi=5, vj=5, a=5, b=5)
            if (d2m_cell == 47) {
                T pex = s_Xworld[108];
                T pey = s_Xworld[109];
                T pez = s_Xworld[110];
                // same-joint pair (intra-joint), joint_jid=5 c_a=0 c_b=0
                // Compute joint-a world frame axes of c_a and c_b body axes
                T aw_0 = s_Xworld[88] * static_cast<T>(1);
                T aw_1 = s_Xworld[89] * static_cast<T>(1);
                T aw_2 = s_Xworld[90] * static_cast<T>(1);
                T bw_0 = s_Xworld[88] * static_cast<T>(1);
                T bw_1 = s_Xworld[89] * static_cast<T>(1);
                T bw_2 = s_Xworld[90] * static_cast<T>(1);
                T alw_0 = static_cast<T>(0);
                T alw_1 = static_cast<T>(0);
                T alw_2 = static_cast<T>(0);
                T blw_0 = static_cast<T>(0);
                T blw_1 = static_cast<T>(0);
                T blw_2 = static_cast<T>(0);
                T pax = s_Xworld[92];
                T pay = s_Xworld[93];
                T paz = s_Xworld[94];
                // Br_world = 0.5 * ([aw]_x [bw]_x + [bw]_x [aw]_x)
                //   = 0.5 * (aw bw^T + bw aw^T) - (aw . bw) I
                T adotb = aw_0*bw_0 + aw_1*bw_1 + aw_2*bw_2;
                T Br_00 = static_cast<T>(0.5) * (aw_0*bw_0 + bw_0*aw_0) - adotb;
                T Br_01 = static_cast<T>(0.5) * (aw_0*bw_1 + bw_0*aw_1);
                T Br_02 = static_cast<T>(0.5) * (aw_0*bw_2 + bw_0*aw_2);
                T Br_10 = static_cast<T>(0.5) * (aw_1*bw_0 + bw_1*aw_0);
                T Br_11 = static_cast<T>(0.5) * (aw_1*bw_1 + bw_1*aw_1) - adotb;
                T Br_12 = static_cast<T>(0.5) * (aw_1*bw_2 + bw_1*aw_2);
                T Br_20 = static_cast<T>(0.5) * (aw_2*bw_0 + bw_2*aw_0);
                T Br_21 = static_cast<T>(0.5) * (aw_2*bw_1 + bw_2*aw_1);
                T Br_22 = static_cast<T>(0.5) * (aw_2*bw_2 + bw_2*aw_2) - adotb;
                T Bt_0 = -(Br_00*pax + Br_01*pay + Br_02*paz);
                T Bt_1 = -(Br_10*pax + Br_11*pay + Br_12*paz);
                T Bt_2 = -(Br_20*pax + Br_21*pay + Br_22*paz);
                T Hxyz_x = Br_00*pex + Br_01*pey + Br_02*pez + Bt_0;
                T Hxyz_y = Br_10*pex + Br_11*pey + Br_12*pez + Bt_1;
                T Hxyz_z = Br_20*pex + Br_21*pey + Br_22*pez + Bt_2;
                // Read [Jw_i]_x and [Jw_j]_x for the H_w correction
                T Si00 = s_Sworld[80];
                T Si10 = s_Sworld[81];
                T Si20 = s_Sworld[82];
                T Si01 = s_Sworld[84];
                T Si11 = s_Sworld[85];
                T Si21 = s_Sworld[86];
                T Si02 = s_Sworld[88];
                T Si12 = s_Sworld[89];
                T Si22 = s_Sworld[90];
                T Sj00 = s_Sworld[80];
                T Sj10 = s_Sworld[81];
                T Sj20 = s_Sworld[82];
                T Sj01 = s_Sworld[84];
                T Sj11 = s_Sworld[85];
                T Sj21 = s_Sworld[86];
                T Sj02 = s_Sworld[88];
                T Sj12 = s_Sworld[89];
                T Sj22 = s_Sworld[90];
                T SiSj00 = Si00*Sj00 + Si01*Sj10 + Si02*Sj20;
                T SiSj01 = Si00*Sj01 + Si01*Sj11 + Si02*Sj21;
                T SiSj02 = Si00*Sj02 + Si01*Sj12 + Si02*Sj22;
                T SiSj10 = Si10*Sj00 + Si11*Sj10 + Si12*Sj20;
                T SiSj11 = Si10*Sj01 + Si11*Sj11 + Si12*Sj21;
                T SiSj12 = Si10*Sj02 + Si11*Sj12 + Si12*Sj22;
                T SiSj20 = Si20*Sj00 + Si21*Sj10 + Si22*Sj20;
                T SiSj21 = Si20*Sj01 + Si21*Sj11 + Si22*Sj21;
                T SiSj22 = Si20*Sj02 + Si21*Sj12 + Si22*Sj22;
                T HW_x = static_cast<T>(0.5) * ((Br_21 - SiSj21) - (Br_12 - SiSj12));
                T HW_y = static_cast<T>(0.5) * ((Br_02 - SiSj02) - (Br_20 - SiSj20));
                T HW_z = static_cast<T>(0.5) * ((Br_10 - SiSj10) - (Br_01 - SiSj01));
                s_end_effector_pose_hessian[(0 + 40) + 0 * 49] = Hxyz_x;
                s_end_effector_pose_hessian[(0 + 40) + 1 * 49] = Hxyz_y;
                s_end_effector_pose_hessian[(0 + 40) + 2 * 49] = Hxyz_z;
                s_end_effector_pose_hessian[(0 + 40) + 3 * 49] = HW_x;
                s_end_effector_pose_hessian[(0 + 40) + 4 * 49] = HW_y;
                s_end_effector_pose_hessian[(0 + 40) + 5 * 49] = HW_z;
            }
            // ee=0 pair (vi=6, vj=6, a=6, b=6)
            if (d2m_cell == 48) {
                T pex = s_Xworld[108];
                T pey = s_Xworld[109];
                T pez = s_Xworld[110];
                // same-joint pair (intra-joint), joint_jid=6 c_a=0 c_b=0
                // Compute joint-a world frame axes of c_a and c_b body axes
                T aw_0 = s_Xworld[104] * static_cast<T>(1);
                T aw_1 = s_Xworld[105] * static_cast<T>(1);
                T aw_2 = s_Xworld[106] * static_cast<T>(1);
                T bw_0 = s_Xworld[104] * static_cast<T>(1);
                T bw_1 = s_Xworld[105] * static_cast<T>(1);
                T bw_2 = s_Xworld[106] * static_cast<T>(1);
                T alw_0 = static_cast<T>(0);
                T alw_1 = static_cast<T>(0);
                T alw_2 = static_cast<T>(0);
                T blw_0 = static_cast<T>(0);
                T blw_1 = static_cast<T>(0);
                T blw_2 = static_cast<T>(0);
                T pax = s_Xworld[108];
                T pay = s_Xworld[109];
                T paz = s_Xworld[110];
                // Br_world = 0.5 * ([aw]_x [bw]_x + [bw]_x [aw]_x)
                //   = 0.5 * (aw bw^T + bw aw^T) - (aw . bw) I
                T adotb = aw_0*bw_0 + aw_1*bw_1 + aw_2*bw_2;
                T Br_00 = static_cast<T>(0.5) * (aw_0*bw_0 + bw_0*aw_0) - adotb;
                T Br_01 = static_cast<T>(0.5) * (aw_0*bw_1 + bw_0*aw_1);
                T Br_02 = static_cast<T>(0.5) * (aw_0*bw_2 + bw_0*aw_2);
                T Br_10 = static_cast<T>(0.5) * (aw_1*bw_0 + bw_1*aw_0);
                T Br_11 = static_cast<T>(0.5) * (aw_1*bw_1 + bw_1*aw_1) - adotb;
                T Br_12 = static_cast<T>(0.5) * (aw_1*bw_2 + bw_1*aw_2);
                T Br_20 = static_cast<T>(0.5) * (aw_2*bw_0 + bw_2*aw_0);
                T Br_21 = static_cast<T>(0.5) * (aw_2*bw_1 + bw_2*aw_1);
                T Br_22 = static_cast<T>(0.5) * (aw_2*bw_2 + bw_2*aw_2) - adotb;
                T Bt_0 = -(Br_00*pax + Br_01*pay + Br_02*paz);
                T Bt_1 = -(Br_10*pax + Br_11*pay + Br_12*paz);
                T Bt_2 = -(Br_20*pax + Br_21*pay + Br_22*paz);
                T Hxyz_x = Br_00*pex + Br_01*pey + Br_02*pez + Bt_0;
                T Hxyz_y = Br_10*pex + Br_11*pey + Br_12*pez + Bt_1;
                T Hxyz_z = Br_20*pex + Br_21*pey + Br_22*pez + Bt_2;
                // Read [Jw_i]_x and [Jw_j]_x for the H_w correction
                T Si00 = s_Sworld[96];
                T Si10 = s_Sworld[97];
                T Si20 = s_Sworld[98];
                T Si01 = s_Sworld[100];
                T Si11 = s_Sworld[101];
                T Si21 = s_Sworld[102];
                T Si02 = s_Sworld[104];
                T Si12 = s_Sworld[105];
                T Si22 = s_Sworld[106];
                T Sj00 = s_Sworld[96];
                T Sj10 = s_Sworld[97];
                T Sj20 = s_Sworld[98];
                T Sj01 = s_Sworld[100];
                T Sj11 = s_Sworld[101];
                T Sj21 = s_Sworld[102];
                T Sj02 = s_Sworld[104];
                T Sj12 = s_Sworld[105];
                T Sj22 = s_Sworld[106];
                T SiSj00 = Si00*Sj00 + Si01*Sj10 + Si02*Sj20;
                T SiSj01 = Si00*Sj01 + Si01*Sj11 + Si02*Sj21;
                T SiSj02 = Si00*Sj02 + Si01*Sj12 + Si02*Sj22;
                T SiSj10 = Si10*Sj00 + Si11*Sj10 + Si12*Sj20;
                T SiSj11 = Si10*Sj01 + Si11*Sj11 + Si12*Sj21;
                T SiSj12 = Si10*Sj02 + Si11*Sj12 + Si12*Sj22;
                T SiSj20 = Si20*Sj00 + Si21*Sj10 + Si22*Sj20;
                T SiSj21 = Si20*Sj01 + Si21*Sj11 + Si22*Sj21;
                T SiSj22 = Si20*Sj02 + Si21*Sj12 + Si22*Sj22;
                T HW_x = static_cast<T>(0.5) * ((Br_21 - SiSj21) - (Br_12 - SiSj12));
                T HW_y = static_cast<T>(0.5) * ((Br_02 - SiSj02) - (Br_20 - SiSj20));
                T HW_z = static_cast<T>(0.5) * ((Br_10 - SiSj10) - (Br_01 - SiSj01));
                s_end_effector_pose_hessian[(0 + 48) + 0 * 49] = Hxyz_x;
                s_end_effector_pose_hessian[(0 + 48) + 1 * 49] = Hxyz_y;
                s_end_effector_pose_hessian[(0 + 48) + 2 * 49] = Hxyz_z;
                s_end_effector_pose_hessian[(0 + 48) + 3 * 49] = HW_x;
                s_end_effector_pose_hessian[(0 + 48) + 4 * 49] = HW_y;
                s_end_effector_pose_hessian[(0 + 48) + 5 * 49] = HW_z;
            }
        }
        __syncthreads();
        //
        // Step 6: rpy chain rule -- replace rows 3..5 with H_rpy = dEinv/dv_j @ J_w_i + Einv @ H_w
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
            int vj = ind % 7;
            int vi = (ind / 7) % 7;
            int ee = ind / 49;
            T cy = s_E_sc[4*ee + 0]; T sy = s_E_sc[4*ee + 1]; T cp = s_E_sc[4*ee + 2]; T sp = s_E_sc[4*ee + 3];
            T inv_cp = static_cast<T>(1) / cp;
            // Einv (3x3); row 0 = roll, row 1 = pitch, row 2 = yaw
            T Einv00 = cy * inv_cp;       T Einv01 = sy * inv_cp;       T Einv02 = static_cast<T>(0);
            T Einv10 = -sy;               T Einv11 = cy;                T Einv12 = static_cast<T>(0);
            T Einv20 = cy * sp * inv_cp;  T Einv21 = sy * sp * inv_cp;  T Einv22 = static_cast<T>(1);
            int dee_base_j = ee * 42 + 6 * vj;
            T drpy_j0 = s_end_effector_pose_gradient[dee_base_j + 3];
            T drpy_j1 = s_end_effector_pose_gradient[dee_base_j + 4];
            T drpy_j2 = s_end_effector_pose_gradient[dee_base_j + 5];
            int dee_base_i = ee * 42 + 6 * vi;
            T drpy_i0 = s_end_effector_pose_gradient[dee_base_i + 3];
            T drpy_i1 = s_end_effector_pose_gradient[dee_base_i + 4];
            T drpy_i2 = s_end_effector_pose_gradient[dee_base_i + 5];
            int hw_base = ee * 294 + 3 * 49 + vi * 7 + vj;
            T Hw_x = s_end_effector_pose_hessian[hw_base + 0 * 49];
            T Hw_y = s_end_effector_pose_hessian[hw_base + 1 * 49];
            T Hw_z = s_end_effector_pose_hessian[hw_base + 2 * 49];
            T dE00 = -cy * sp * drpy_j1 - sy * cp * drpy_j2;
            T dE01 = -cy * drpy_j2;
            // dE02 = 0
            T dE10 = -sy * sp * drpy_j1 + cy * cp * drpy_j2;
            T dE11 = -sy * drpy_j2;
            // dE12 = 0
            T dE20 = -cp * drpy_j1;
            // dE21 = dE22 = 0
            // row 0 (roll): U_0 = Einv[0,:] @ dE_total
            T U0_0 = Einv00 * dE00 + Einv01 * dE10 + Einv02 * dE20;
            T U0_1 = Einv00 * dE01 + Einv01 * dE11;
            // row 1 (pitch)
            T U1_0 = Einv10 * dE00 + Einv11 * dE10 + Einv12 * dE20;
            T U1_1 = Einv10 * dE01 + Einv11 * dE11;
            // row 2 (yaw)
            T U2_0 = Einv20 * dE00 + Einv21 * dE10 + Einv22 * dE20;
            T U2_1 = Einv20 * dE01 + Einv21 * dE11;
            T H_rpy_0 = -(U0_0 * drpy_i0 + U0_1 * drpy_i1) + (Einv00 * Hw_x + Einv01 * Hw_y + Einv02 * Hw_z);
            T H_rpy_1 = -(U1_0 * drpy_i0 + U1_1 * drpy_i1) + (Einv10 * Hw_x + Einv11 * Hw_y + Einv12 * Hw_z);
            T H_rpy_2 = -(U2_0 * drpy_i0 + U2_1 * drpy_i1) + (Einv20 * Hw_x + Einv21 * Hw_y + Einv22 * Hw_z);
            int out_base = ee * 294 + 3 * 49 + vi * 7 + vj;
            s_end_effector_pose_hessian[out_base + 0 * 49] = H_rpy_0;
            s_end_effector_pose_hessian[out_base + 1 * 49] = H_rpy_1;
            s_end_effector_pose_hessian[out_base + 2 * 49] = H_rpy_2;
        }
        __syncthreads();
        //
        // Step 7: symmetrize H_rpy (rows 3..5) over (i, j)
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
            int e = ind / 147;
            int cji = ind % 147;
            int rrow = cji / 49;   // 0..2 -> c = 3 + rrow
            int ji = cji % 49;
            int i = ji / 7; int j = ji % 7;
            if (i <= j) {
                int c = 3 + rrow;
                int idx_ij = e * 294 + c * 49 + i * 7 + j;
                int idx_ji = e * 294 + c * 49 + j * 7 + i;
                T avg = static_cast<T>(0.5) * (s_end_effector_pose_hessian[idx_ij] + s_end_effector_pose_hessian[idx_ji]);
                s_end_effector_pose_hessian[idx_ij] = avg;
                if (i != j) { s_end_effector_pose_hessian[idx_ji] = avg; }
            }
        }
        __syncthreads();
    }

    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Inline-CUDA users: at TIER_LITE/TIER_MINIMAL the large s_end_effector_pose_hessian output (~294*sizeof(T) bytes) moves from shared memory to d_workspace, freeing smem for the caller's outer kernel
     *
     * @param s_end_effector_pose_hessian is a pointer to shared memory of size 6*NUM_VEL*NUM_VEL*NUM_EE where NUM_VEL = 7 and NUM_EE = 1 (d^2/dv^2 tangent, pinocchio convention)
     * @param s_end_effector_pose_gradient is a pointer to shared memory of size 6*NUM_VEL*NUM_EE (d/dv tangent Jacobian)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_workspace is the global scratch buffer; size END_EFFECTOR_POSE_HESSIAN_DEVICE_INLINE_WORKSPACE_BYTES<T, RESOURCE_TIER>() bytes (= 0 at TIER_SHARED, 294*sizeof(T) at TIER_LITE+). Pass nullptr at TIER_SHARED
     */
    template <typename T, int RESOURCE_TIER = TIER_SHARED>
    __device__
    void end_effector_pose_hessian_device(T *s_end_effector_pose_hessian, T *s_end_effector_pose_gradient, const T *s_q, const robotModel<T> *d_robotModel, T *d_workspace = nullptr) {
        // GRID shared arena layout
        //   T s_XmatsHom[144]
        //   T s_temp[260]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(144);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(260);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
