            assert(s_arena_offset == grid_shared_arena_bytes<T>(151, 0, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            T *s_end_effector_pose_gradient = d_end_effector_pose_gradient;
            T *s_eegrad_temp = reinterpret_cast<T *>(&d_workspace[GRID_END_EFFECTOR_POSE_GRADIENT_WORKSPACE_DXHOM_OFFSET_BYTES<T>()]);
            s_temp = s_eegrad_temp;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 7; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (7)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_end_effector_pose_gradient into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_end_effector_pose_gradient)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_end_effector_pose_gradient)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_end_effector_pose_gradient)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (7)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (7)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (7)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_gradient_inner_EE<T, false>(s_end_effector_pose_gradient, s_q, s_XmatsHom, nullptr, s_topology_helpers, s_temp, s_eegrad_temp, s_linalg_smem);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_end_effector_pose_gradient)[rep & 1023] = reinterpret_cast<const volatile T *>(s_end_effector_pose_gradient)[rep & 7]; }
            }
        }
    }

    /**
     * Computes the Gradient of the End Effector Pose with respect to joint position
     *
     * @param d_end_effector_pose_gradient is the vector of end effector positions gradients
     * @param d_workspace is the generated global spill workspace
     * @param d_q is the vector of joint positions
     * @param stride_q is the stide between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void end_effector_pose_gradient_kernel_EE(T *d_end_effector_pose_gradient, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_end_effector_pose_gradient[42]
            //   T s_XmatsHom[144]
            //   T s_temp[190]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_end_effector_pose_gradient = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(144);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(190);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(383, 0, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            (void)d_workspace;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_k = &d_q[k*stride_q];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = d_q_k[ind];
                }
                __syncthreads();
                // compute
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_gradient_inner_EE<T, true>(s_end_effector_pose_gradient, s_q, s_XmatsHom, nullptr, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
                __syncthreads();
                // save down to global
                T *d_end_effector_pose_gradient_k = &d_end_effector_pose_gradient[k*42];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 42; ind += blockDim.x*blockDim.y){
                    d_end_effector_pose_gradient_k[ind] = s_end_effector_pose_gradient[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_end_effector_pose_gradient[42]
            //   T s_XmatsHom[144]
            //   T s_temp[190]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_end_effector_pose_gradient = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(144);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(190);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(383, 0, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            (void)d_workspace;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_k = &d_q[k*stride_q];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = d_q_k[ind];
                }
                __syncthreads();
                // compute
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_gradient_inner_EE<T, true>(s_end_effector_pose_gradient, s_q, s_XmatsHom, nullptr, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
                __syncthreads();
                // save down to global
                T *d_end_effector_pose_gradient_k = &d_end_effector_pose_gradient[k*42];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 42; ind += blockDim.x*blockDim.y){
                    d_end_effector_pose_gradient_k[ind] = s_end_effector_pose_gradient[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_XmatsHom[144]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(144);
            T *s_temp = nullptr;
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(151, 0, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_k = &d_q[k*stride_q];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = d_q_k[ind];
                }
                __syncthreads();
                T *s_end_effector_pose_gradient = &d_end_effector_pose_gradient[k*42];
                T *s_eegrad_temp = reinterpret_cast<T *>(&d_workspace[k*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_END_EFFECTOR_POSE_GRADIENT_WORKSPACE_DXHOM_OFFSET_BYTES<T>()]);
                s_temp = s_eegrad_temp;
                // compute
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_gradient_inner_EE<T, false>(s_end_effector_pose_gradient, s_q, s_XmatsHom, nullptr, s_topology_helpers, s_temp, s_eegrad_temp, s_linalg_smem);
                __syncthreads();
            }
        }
    }

    /**
     * Computes the Gradient of the End Effector Pose with respect to joint position
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_gradient_EE(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose_gradient requires all-data or kinematics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose_gradient", END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        if (USE_COMPRESSED_MEM) {end_effector_pose_gradient_kernel_EE<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_gradient_kernel_EE<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_end_effector_pose_gradient,hd_data->d_end_effector_pose_gradient,6*NUM_EES*NUM_VEL*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Computes the Gradient of the End Effector Pose with respect to joint position
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_gradient_EE_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                              const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose_gradient requires all-data or kinematics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose_gradient", END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()));}
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        if (USE_COMPRESSED_MEM) {end_effector_pose_gradient_kernel_EE<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_gradient_kernel_EE<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_end_effector_pose_gradient,hd_data->d_end_effector_pose_gradient,6*NUM_EES*NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call END_EFFECTOR_POSE_GRADIENT %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Computes the Gradient of the End Effector Pose with respect to joint position
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_gradient_EE_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                             const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose_gradient requires all-data or kinematics gridData");
        int stride_q = USE_COMPRESSED_MEM ? NUM_JOINTS: 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose_gradient", END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        if (USE_COMPRESSED_MEM) {end_effector_pose_gradient_kernel_EE<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_gradient_kernel_EE<T, RESOURCE_TIER><<<block_dimms,thread_dimms,END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        if (GRID_END_EFFECTOR_POSE_GRADIENT_USES_WORKSPACE_TEMP_ANY) {gpuErrchk(grid_end_l2_persisting(0));}
    }

    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Closed-form analytic d2(pose)/dv2; matches RBDReference.end_effector_pose_hessian_analytic (which agrees with pinocchio getJointKinematicHessian(LOCAL_WORLD_ALIGNED) to the FD floor fleet-wide; CUDA confirmed on iiwa14-fixed + go2-floating).
     *   Inner-owns scratch placement: the large nv^2 output s_end_effector_pose_hessian moves to d_workspace when !OUT_IN_SMEM. The s_Xworld+s_Sworld+s_E_sc scratch in s_temp stays in smem at every tier.
     *
     * @param s_end_effector_pose_hessian is a pointer to memory of size 6*NUM_VEL*NUM_VEL*NUM_EE where NUM_VEL = 7 and NUM_EE = 1 (d^2(pose)/dv^2 tangent-space Hessian, pinocchio convention)
     * @param s_end_effector_pose_gradient is a pointer to memory of size 6*NUM_VEL*NUM_EE (the d/dv tangent Jacobian at q)
     * @param s_q is the vector of joint positions (size NUM_POS = 7; kept for signature compatibility, unused by the analytic path)
     * @param s_Xhom is the per-joint LOCAL homogeneous-transform buffer (read-only)
     * @param s_temp is helper shared memory of size 260 (s_Xworld | s_Sworld | s_E_sc; always kept in smem)
     * @param d_workspace is the global spill arena s_end_effector_pose_hessian is repointed at when !OUT_IN_SMEM (else unused)
     * @param d_robotModel is the model-specific helper struct (kept for signature compatibility, unused by the analytic path)
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_linalg_smem is optional byte-addressed shared memory (reserved; unused by this inner)
     */
    template <typename T, bool OUT_IN_SMEM = true>
    __device__
    void end_effector_pose_hessian_inner_EE(T *s_end_effector_pose_hessian, T *s_end_effector_pose_gradient, const T *s_q, T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, const robotModel<T> *d_robotModel, unsigned char *s_linalg_smem) {
        if constexpr (!OUT_IN_SMEM) { s_end_effector_pose_hessian = d_workspace; } else { (void)d_workspace; }
        (void)s_q; (void)d_robotModel; (void)s_linalg_smem;
        // scratch in s_temp: s_Xworld (16*n_joints) | s_Sworld (16*nv*num_ees) | s_E_sc (4*num_ees)
        T *s_Xworld = &s_temp[0];
        T *s_Sworld = &s_temp[144];  // per-DOF world-frame 4x4 generator (S_i_world)
        T *s_E_sc   = &s_temp[256];  // cy, sy, cp, sp per ee
        //
        // Step 1: forward kinematics -- build s_Xworld[16*j] for every joint via BFS-level chain-up
        //
        // BFS level 0 -> joints [0]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 0; par = -1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 1 -> joints [1]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 1; par = 0; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 2 -> joints [2]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 2; par = 1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 3 -> joints [3]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 3; par = 2; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 4 -> joints [4]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 4; par = 3; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 5 -> joints [5]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 5; par = 4; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 6 -> joints [6]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 6; par = 5; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        //
        // Step 1b: world transform of the fixed kinematic target(s): Xworld[anchor] = Xworld[parent] @ Xhom_local[anchor]
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int anc; int par;
                 if (slot < 1){ anc = 7; par = 6; }
            s_Xworld[16*anc + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*anc + 4*col]);
        }
        __syncthreads();
        //
        // Step 2: build per-DOF world-frame 4x4 generator S_i_world
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 112; ind += blockDim.x*blockDim.y){
            s_Sworld[ind] = static_cast<T>(0);
        }
        __syncthreads();
        for(int sworld_slot = threadIdx.x + threadIdx.y*blockDim.x; sworld_slot < 7; sworld_slot += blockDim.x*blockDim.y){
            if (sworld_slot == 0) {
                // ee=0 vi=0 jid=0 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[8] * static_cast<T>(1);
                    T axw_1 = s_Xworld[9] * static_cast<T>(1);
                    T axw_2 = s_Xworld[10] * static_cast<T>(1);
                    T pjx = s_Xworld[12];
                    T pjy = s_Xworld[13];
                    T pjz = s_Xworld[14];
                    s_Sworld[0] = static_cast<T>(0);
                    s_Sworld[1] =  axw_2;
                    s_Sworld[2] = -axw_1;
                    s_Sworld[4] = -axw_2;
                    s_Sworld[5] = static_cast<T>(0);
                    s_Sworld[6] =  axw_0;
                    s_Sworld[8] =  axw_1;
                    s_Sworld[9] = -axw_0;
                    s_Sworld[10] = static_cast<T>(0);
                    s_Sworld[12] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[13] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[14] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 1) {
                // ee=0 vi=1 jid=1 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[24] * static_cast<T>(1);
                    T axw_1 = s_Xworld[25] * static_cast<T>(1);
                    T axw_2 = s_Xworld[26] * static_cast<T>(1);
                    T pjx = s_Xworld[28];
                    T pjy = s_Xworld[29];
                    T pjz = s_Xworld[30];
                    s_Sworld[16] = static_cast<T>(0);
                    s_Sworld[17] =  axw_2;
                    s_Sworld[18] = -axw_1;
                    s_Sworld[20] = -axw_2;
                    s_Sworld[21] = static_cast<T>(0);
                    s_Sworld[22] =  axw_0;
                    s_Sworld[24] =  axw_1;
                    s_Sworld[25] = -axw_0;
                    s_Sworld[26] = static_cast<T>(0);
                    s_Sworld[28] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[29] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[30] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 2) {
                // ee=0 vi=2 jid=2 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[40] * static_cast<T>(1);
                    T axw_1 = s_Xworld[41] * static_cast<T>(1);
                    T axw_2 = s_Xworld[42] * static_cast<T>(1);
                    T pjx = s_Xworld[44];
                    T pjy = s_Xworld[45];
                    T pjz = s_Xworld[46];
                    s_Sworld[32] = static_cast<T>(0);
                    s_Sworld[33] =  axw_2;
                    s_Sworld[34] = -axw_1;
                    s_Sworld[36] = -axw_2;
                    s_Sworld[37] = static_cast<T>(0);
                    s_Sworld[38] =  axw_0;
                    s_Sworld[40] =  axw_1;
                    s_Sworld[41] = -axw_0;
                    s_Sworld[42] = static_cast<T>(0);
                    s_Sworld[44] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[45] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[46] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 3) {
                // ee=0 vi=3 jid=3 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[56] * static_cast<T>(1);
                    T axw_1 = s_Xworld[57] * static_cast<T>(1);
                    T axw_2 = s_Xworld[58] * static_cast<T>(1);
                    T pjx = s_Xworld[60];
                    T pjy = s_Xworld[61];
                    T pjz = s_Xworld[62];
                    s_Sworld[48] = static_cast<T>(0);
                    s_Sworld[49] =  axw_2;
                    s_Sworld[50] = -axw_1;
                    s_Sworld[52] = -axw_2;
                    s_Sworld[53] = static_cast<T>(0);
                    s_Sworld[54] =  axw_0;
                    s_Sworld[56] =  axw_1;
                    s_Sworld[57] = -axw_0;
                    s_Sworld[58] = static_cast<T>(0);
                    s_Sworld[60] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[61] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[62] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 4) {
                // ee=0 vi=4 jid=4 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[72] * static_cast<T>(1);
                    T axw_1 = s_Xworld[73] * static_cast<T>(1);
                    T axw_2 = s_Xworld[74] * static_cast<T>(1);
                    T pjx = s_Xworld[76];
                    T pjy = s_Xworld[77];
                    T pjz = s_Xworld[78];
                    s_Sworld[64] = static_cast<T>(0);
                    s_Sworld[65] =  axw_2;
                    s_Sworld[66] = -axw_1;
                    s_Sworld[68] = -axw_2;
                    s_Sworld[69] = static_cast<T>(0);
                    s_Sworld[70] =  axw_0;
                    s_Sworld[72] =  axw_1;
                    s_Sworld[73] = -axw_0;
                    s_Sworld[74] = static_cast<T>(0);
                    s_Sworld[76] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[77] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[78] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 5) {
                // ee=0 vi=5 jid=5 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[88] * static_cast<T>(1);
                    T axw_1 = s_Xworld[89] * static_cast<T>(1);
                    T axw_2 = s_Xworld[90] * static_cast<T>(1);
                    T pjx = s_Xworld[92];
                    T pjy = s_Xworld[93];
                    T pjz = s_Xworld[94];
                    s_Sworld[80] = static_cast<T>(0);
                    s_Sworld[81] =  axw_2;
                    s_Sworld[82] = -axw_1;
                    s_Sworld[84] = -axw_2;
                    s_Sworld[85] = static_cast<T>(0);
                    s_Sworld[86] =  axw_0;
                    s_Sworld[88] =  axw_1;
                    s_Sworld[89] = -axw_0;
                    s_Sworld[90] = static_cast<T>(0);
                    s_Sworld[92] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[93] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[94] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 6) {
                // ee=0 vi=6 jid=6 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[104] * static_cast<T>(1);
                    T axw_1 = s_Xworld[105] * static_cast<T>(1);
                    T axw_2 = s_Xworld[106] * static_cast<T>(1);
                    T pjx = s_Xworld[108];
                    T pjy = s_Xworld[109];
                    T pjz = s_Xworld[110];
                    s_Sworld[96] = static_cast<T>(0);
                    s_Sworld[97] =  axw_2;
                    s_Sworld[98] = -axw_1;
                    s_Sworld[100] = -axw_2;
                    s_Sworld[101] = static_cast<T>(0);
                    s_Sworld[102] =  axw_0;
                    s_Sworld[104] =  axw_1;
                    s_Sworld[105] = -axw_0;
                    s_Sworld[106] = static_cast<T>(0);
                    s_Sworld[108] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[109] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[110] = pjx*axw_1 - pjy*axw_0;
                }
            }
        }
        __syncthreads();
        //
        // Step 3: extract (cy, sy, cp, sp) for E(rpy)^-1 / dE/drpy
        //
        for(int ee = threadIdx.x + threadIdx.y*blockDim.x; ee < 1; ee += blockDim.x*blockDim.y){
            const int ee_jid = 7;
            T R20 = s_Xworld[16*ee_jid + 2];
            T R21 = s_Xworld[16*ee_jid + 6];
            T R22 = s_Xworld[16*ee_jid + 10];
            T R10 = s_Xworld[16*ee_jid + 1];
            T R00 = s_Xworld[16*ee_jid + 0];
            T cp_term = sqrt(R22*R22 + R21*R21);
            T yaw = atan2(R10, R00);
            T pitch = atan2(-R20, cp_term);
            s_E_sc[4*ee + 0] = cos(yaw);
            s_E_sc[4*ee + 1] = sin(yaw);
            s_E_sc[4*ee + 2] = cos(pitch);
            s_E_sc[4*ee + 3] = sin(pitch);
        }
        __syncthreads();
        //
        // Step 4: write s_end_effector_pose_gradient = [J_v ; E(rpy)^-1 * J_w] from S_world
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 42; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int rem = ind / 6; int vi = rem % 7; int ee = rem / 7;
            int s_base = 16 * (ee * 7 + vi);
            T wx = s_Sworld[s_base + 6];   // S[2,1]
            T wy = s_Sworld[s_base + 8];   // S[0,2]
            T wz = s_Sworld[s_base + 1];   // S[1,0]
            T s03 = s_Sworld[s_base + 12]; // S[0,3]
            T s13 = s_Sworld[s_base + 13]; // S[1,3]
            T s23 = s_Sworld[s_base + 14]; // S[2,3]
            if (row < 3) {
                const int ee_jid = 7;
                T pex = s_Xworld[16*ee_jid + 12]; T pey = s_Xworld[16*ee_jid + 13]; T pez = s_Xworld[16*ee_jid + 14];
                T Jv0 = (wy*pez - wz*pey) + s03;
                T Jv1 = (wz*pex - wx*pez) + s13;
                T Jv2 = (wx*pey - wy*pex) + s23;
                T outv;
                if (row == 0) outv = Jv0; else if (row == 1) outv = Jv1; else outv = Jv2;
                s_end_effector_pose_gradient[ind] = outv;
            }
            else {
                T cy = s_E_sc[4*ee + 0]; T sy = s_E_sc[4*ee + 1]; T cp = s_E_sc[4*ee + 2]; T sp = s_E_sc[4*ee + 3];
                T outv;
                if (row == 3) { outv = (cy*wx + sy*wy) / cp; }
                else if (row == 4) { outv = -sy*wx + cy*wy; }
                else { outv = (sp / cp) * (cy*wx + sy*wy) + wz; }
                s_end_effector_pose_gradient[ind] = outv;
            }
        }
        __syncthreads();
        //
        // Step 5a: zero the full end_effector_pose_hessian output (out-of-chain pairs stay zero)
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 294; ind += blockDim.x*blockDim.y){
            s_end_effector_pose_hessian[ind] = static_cast<T>(0);
        }
        __syncthreads();
        //
        // Step 5b: per (ee, i, j) pair: d2M = S_i_world * S_j_world * X_ee (for a < b)
        //   or B_world * X_ee (intra-joint). Writes H_xyz to rows 0..2 and (temporarily)
        //   the world-angular Hessian H_w to rows 3..5; the rpy chain rule in Step 6
        //   then overwrites rows 3..5 with the proper H_rpy.
        //
        for(int d2m_cell = threadIdx.x + threadIdx.y*blockDim.x; d2m_cell < 49; d2m_cell += blockDim.x*blockDim.y){
            // Cross-joint cells (vast majority): one shared body driven by a baked
            // per-cell offset table; collapses the old O(n_cross) if==k ladder.
            static const int s_d2ee_cross_tab[252] = {0, 16, 0, 16, 112, 1, 0, 32, 0, 32, 112, 2, 0, 48, 0, 48, 112, 3, 0, 64, 0, 64, 112, 4, 0, 80, 0, 80, 112, 5, 0, 96, 0, 96, 112, 6, 0, 16, 16, 0, 112, 7, 16, 32, 16, 32, 112, 9, 16, 48, 16, 48, 112, 10, 16, 64, 16, 64, 112, 11, 16, 80, 16, 80, 112, 12, 16, 96, 16, 96, 112, 13, 0, 32, 32, 0, 112, 14, 16, 32, 32, 16, 112, 15, 32, 48, 32, 48, 112, 17, 32, 64, 32, 64, 112, 18, 32, 80, 32, 80, 112, 19, 32, 96, 32, 96, 112, 20, 0, 48, 48, 0, 112, 21, 16, 48, 48, 16, 112, 22, 32, 48, 48, 32, 112, 23, 48, 64, 48, 64, 112, 25, 48, 80, 48, 80, 112, 26, 48, 96, 48, 96, 112, 27, 0, 64, 64, 0, 112, 28, 16, 64, 64, 16, 112, 29, 32, 64, 64, 32, 112, 30, 48, 64, 64, 48, 112, 31, 64, 80, 64, 80, 112, 33, 64, 96, 64, 96, 112, 34, 0, 80, 80, 0, 112, 35, 16, 80, 80, 16, 112, 36, 32, 80, 80, 32, 112, 37, 48, 80, 80, 48, 112, 38, 64, 80, 80, 64, 112, 39, 80, 96, 80, 96, 112, 41, 0, 96, 96, 0, 112, 42, 16, 96, 96, 16, 112, 43, 32, 96, 96, 32, 112, 44, 48, 96, 96, 48, 112, 45, 64, 96, 96, 64, 112, 46, 80, 96, 96, 80, 112, 47};
            if (d2m_cell < 42) {
                const int *row = &s_d2ee_cross_tab[6 * d2m_cell];
                int prox_base = row[0]; int dist_base = row[1];
                int si_base = row[2]; int sj_base = row[3];
                int pee_base = row[4]; int out_base = row[5];
                T pex = s_Xworld[pee_base + 12];
                T pey = s_Xworld[pee_base + 13];
                T pez = s_Xworld[pee_base + 14];
                // Read S_prox (chain proximal) rows 0..2
                T P00 = s_Sworld[prox_base + 0];
                T P10 = s_Sworld[prox_base + 1];
                T P20 = s_Sworld[prox_base + 2];
                T P01 = s_Sworld[prox_base + 4];
                T P11 = s_Sworld[prox_base + 5];
                T P21 = s_Sworld[prox_base + 6];
                T P02 = s_Sworld[prox_base + 8];
                T P12 = s_Sworld[prox_base + 9];
                T P22 = s_Sworld[prox_base + 10];
                T P03 = s_Sworld[prox_base + 12];
                T P13 = s_Sworld[prox_base + 13];
                T P23 = s_Sworld[prox_base + 14];
                // Read S_dist (chain distal) rows 0..2
                T D00 = s_Sworld[dist_base + 0];
                T D10 = s_Sworld[dist_base + 1];
                T D20 = s_Sworld[dist_base + 2];
                T D01 = s_Sworld[dist_base + 4];
                T D11 = s_Sworld[dist_base + 5];
                T D21 = s_Sworld[dist_base + 6];
                T D02 = s_Sworld[dist_base + 8];
                T D12 = s_Sworld[dist_base + 9];
                T D22 = s_Sworld[dist_base + 10];
                T D03 = s_Sworld[dist_base + 12];
                T D13 = s_Sworld[dist_base + 13];
