        gpuErrchk(cudaMemcpy(hd_data->h_end_effector_pose_hessian,hd_data->d_end_effector_pose_hessian,6*NUM_EES*NUM_VEL*NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
