    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * @param d_c is the vector of output torques
     * @param d_q_dq is the vector of joint positions and velocities
     * @param stride_q_qd is the stide between each q, qd
     * @param d_qdd is the vector of joint accelerations
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant,num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void inverse_dynamics_kernel_single_timing(T *d_c, const T *d_q_qd, const int stride_q_qd, const T *d_qdd, T *d_f_ext, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q_qd[14]
        //   T s_c[7]
        //   T s_vaf[126]
        //   T s_qdd[7]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(14);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_c = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(700, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
        // load to shared mem
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
            s_q_qd[ind] = d_q_qd[ind];
        }
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
            s_qdd[ind] = d_qdd[ind];
        }
        __syncthreads();
        // compute with NUM_TIMESTEPS as NUM_REPS for timing
        for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
            // anti-LICM: volatile reload of inputs each rep
            for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 14; _aopt_i += blockDim.x*blockDim.y){
                reinterpret_cast<volatile T *>(s_q_qd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd)[_aopt_i];
            }
            for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 7; _aopt_i += blockDim.x*blockDim.y){
                reinterpret_cast<volatile T *>(s_qdd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_qdd)[_aopt_i];
            }
            __syncthreads();
            // anti-LICM (1/2): stomp one input slot with `rep`
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                reinterpret_cast<volatile T *>(s_q_qd)[rep % (14)] = static_cast<T>(rep);
                reinterpret_cast<volatile T *>(s_qdd)[rep % (7)] = static_cast<T>(rep);
            }
            // anti-LICM (2/2): feedback prev rep's d_c into s_q_qd (true loop-carried dep)
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_c)[(rep + 0x3FF) & 0x3FF];
                T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_c)[(rep + 0x3FE) & 0x3FF];
                T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_c)[(rep + 0x3FD) & 0x3FF];
                reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (14)] += _aopt_fb1;
                reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (14)] += _aopt_fb2;
                reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (14)] += _aopt_fb3;
            }
            __syncthreads();
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            inverse_dynamics_inner<T>(s_c, s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            __syncthreads();
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_c)[rep & 1023] = reinterpret_cast<const volatile T *>(s_c)[rep & 7]; }
        }
        // save down to global
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
            d_c[ind] = s_c[ind];
        }
        __syncthreads();
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * @param d_c is the vector of output torques
     * @param d_q_dq is the vector of joint positions and velocities
     * @param stride_q_qd is the stide between each q, qd
     * @param d_qdd is the vector of joint accelerations
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant,num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void inverse_dynamics_kernel(T *d_c, const T *d_q_qd, const int stride_q_qd, const T *d_qdd, T *d_f_ext, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q_qd[14]
        //   T s_c[7]
        //   T s_vaf[126]
        //   T s_qdd[7]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(14);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_c = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(700, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            // load to shared mem
            const T *d_q_qd_k = &d_q_qd[k*stride_q_qd];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd_k[ind];
            }
            const T *d_qdd_k = &d_qdd[k*7];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_qdd[ind] = d_qdd_k[ind];
            }
            __syncthreads();
            // compute
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            inverse_dynamics_inner<T>(s_c, s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            __syncthreads();
            // save down to global
            T *d_c_k = &d_c[k*7];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                d_c_k[ind] = s_c[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * Notes:
     *   optimized for qdd = 0
     *
     * @param d_c is the vector of output torques
     * @param d_q_dq is the vector of joint positions and velocities
     * @param stride_q_qd is the stide between each q, qd
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant,num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void inverse_dynamics_kernel_single_timing(T *d_c, const T *d_q_qd, const int stride_q_qd, T *d_f_ext, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q_qd[14]
        //   T s_c[7]
        //   T s_vaf[126]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(14);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_c = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(693, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
        // load to shared mem
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
            s_q_qd[ind] = d_q_qd[ind];
        }
        __syncthreads();
        // compute with NUM_TIMESTEPS as NUM_REPS for timing
        for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
            // anti-LICM: volatile reload of inputs each rep
            for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 14; _aopt_i += blockDim.x*blockDim.y){
                reinterpret_cast<volatile T *>(s_q_qd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd)[_aopt_i];
            }
            __syncthreads();
            // anti-LICM (1/2): stomp one input slot with `rep`
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                reinterpret_cast<volatile T *>(s_q_qd)[rep % (14)] = static_cast<T>(rep);
            }
            // anti-LICM (2/2): feedback prev rep's d_c into s_q_qd (true loop-carried dep)
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_c)[(rep + 0x3FF) & 0x3FF];
                T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_c)[(rep + 0x3FE) & 0x3FF];
                T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_c)[(rep + 0x3FD) & 0x3FF];
                reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (14)] += _aopt_fb1;
                reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (14)] += _aopt_fb2;
                reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (14)] += _aopt_fb3;
            }
            __syncthreads();
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            inverse_dynamics_inner<T>(s_c, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            __syncthreads();
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_c)[rep & 1023] = reinterpret_cast<const volatile T *>(s_c)[rep & 7]; }
        }
        // save down to global
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
            d_c[ind] = s_c[ind];
        }
        __syncthreads();
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * Notes:
     *   optimized for qdd = 0
     *
     * @param d_c is the vector of output torques
     * @param d_q_dq is the vector of joint positions and velocities
     * @param stride_q_qd is the stide between each q, qd
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant,num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void inverse_dynamics_kernel(T *d_c, const T *d_q_qd, const int stride_q_qd, T *d_f_ext, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q_qd[14]
        //   T s_c[7]
        //   T s_vaf[126]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(14);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_c = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(693, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            // load to shared mem
            const T *d_q_qd_k = &d_q_qd[k*stride_q_qd];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd_k[ind];
            }
            __syncthreads();
            // compute
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            inverse_dynamics_inner<T>(s_c, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            __syncthreads();
            // save down to global
            T *d_c_k = &d_c[k*7];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                d_c_k[ind] = s_c[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_QDD_FLAG = false, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void inverse_dynamics(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "inverse_dynamics requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        if (USE_QDD_FLAG) {gpuErrchk(cudaMemcpyAsync(hd_data->d_qdd,hd_data->h_qdd,NUM_JOINTS*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[1]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("inverse_dynamics", INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()));
        if (USE_QDD_FLAG) {
            if (USE_COMPRESSED_MEM) {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd,stride_q_qd,hd_data->d_qdd, hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
            else                    {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_qdd, hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
        }
        else {
            if (USE_COMPRESSED_MEM) {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
            else                    {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
        }
        gpuErrchkKernel();
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_c,hd_data->d_c,NUM_JOINTS*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_QDD_FLAG = false, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void inverse_dynamics_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "inverse_dynamics requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        if (USE_QDD_FLAG) {gpuErrchk(cudaMemcpyAsync(hd_data->d_qdd,hd_data->h_qdd,NUM_JOINTS*sizeof(T),cudaMemcpyHostToDevice,streams[1]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("inverse_dynamics", INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        if (USE_QDD_FLAG) {
            if (USE_COMPRESSED_MEM) {inverse_dynamics_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd,stride_q_qd,hd_data->d_qdd, hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
            else                    {inverse_dynamics_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_qdd, hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
        }
        else {
            if (USE_COMPRESSED_MEM) {inverse_dynamics_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
            else                    {inverse_dynamics_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
        }
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_c,hd_data->d_c,NUM_JOINTS*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call INVERSE_DYNAMICS %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_QDD_FLAG = false, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void inverse_dynamics_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "inverse_dynamics requires all-data or dynamics gridData");
        int stride_q_qd = USE_COMPRESSED_MEM ? 2*NUM_JOINTS: 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("inverse_dynamics", INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()));
        if (USE_QDD_FLAG) {
            if (USE_COMPRESSED_MEM) {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd,stride_q_qd,hd_data->d_qdd, hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
            else                    {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_qdd, hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
        }
        else {
            if (USE_COMPRESSED_MEM) {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
            else                    {inverse_dynamics_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);}
        }
        gpuErrchkKernel();
    }

    /**
     * Compute the joint-torque regressor Y (tau = Y . pi)
     *
     * Notes:
     *   Assumes the XI matricies have already been updated for the given q
     *   tau = Y . pi with pi_i = [m, m*c(3), I_O(6)=[Ixx,Ixy,Ixz,Iyy,Iyz,Izz]] per link
     *
     * @param s_Y is the output joint-torque regressor, row-major nv x 10*NUM_BODIES = 490
     * @param s_vaf is scratch of size 18*NUM_JOINTS = 126 (RNEA v|a|f)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_qdd is the vector of joint accelerations
     * @param s_temp is helper shared memory of size 42
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param gravity is the gravity constant
     */
    template <typename T>
    __device__
    void inverse_dynamics_regressor_inner(T *s_Y, T *s_vaf, const T *s_q, const T *s_qd, const T *s_qdd, T *s_XImats, int *s_topology_helpers, T *s_temp, const T gravity) {
        // forward RNEA sweep: populate s_vaf v|a (reuse RNEA vaf inner)
        inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
        __syncthreads();
        // zero the regressor
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 490; ind += blockDim.x*blockDim.y){
            s_Y[ind] = static_cast<T>(0);
        }
        __syncthreads();
        // build Y: per (link, param) propagate the 6x10 body regressor up the tree
        for(int col = threadIdx.x + threadIdx.y*blockDim.x; col < 70; col += blockDim.x*blockDim.y){
            int link_i = col / 10; int param_k = col % 10;
            T f[6]; T dIv[6]; T dIa[6]; T crfv[6];
            const T *v_i = &s_vaf[6*link_i];
            const T *a_i = &s_vaf[42 + 6*link_i];
            switch (param_k) {
                case 0: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = v_i[3];
                    dIv[4] = v_i[4];
                    dIv[5] = v_i[5];
                    dIa[0] = static_cast<T>(0);
                    dIa[1] = static_cast<T>(0);
                    dIa[2] = static_cast<T>(0);
                    dIa[3] = a_i[3];
                    dIa[4] = a_i[4];
                    dIa[5] = a_i[5];
                    break;
                }
                case 1: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] =  - v_i[5];
                    dIv[2] = v_i[4];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = v_i[2];
                    dIv[5] =  - v_i[1];
                    dIa[0] = static_cast<T>(0);
                    dIa[1] =  - a_i[5];
                    dIa[2] = a_i[4];
                    dIa[3] = static_cast<T>(0);
                    dIa[4] = a_i[2];
                    dIa[5] =  - a_i[1];
                    break;
                }
                case 2: {
                    dIv[0] = v_i[5];
                    dIv[1] = static_cast<T>(0);
                    dIv[2] =  - v_i[3];
                    dIv[3] =  - v_i[2];
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = v_i[0];
                    dIa[0] = a_i[5];
                    dIa[1] = static_cast<T>(0);
                    dIa[2] =  - a_i[3];
                    dIa[3] =  - a_i[2];
                    dIa[4] = static_cast<T>(0);
                    dIa[5] = a_i[0];
                    break;
                }
                case 3: {
                    dIv[0] =  - v_i[4];
                    dIv[1] = v_i[3];
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = v_i[1];
                    dIv[4] =  - v_i[0];
                    dIv[5] = static_cast<T>(0);
                    dIa[0] =  - a_i[4];
                    dIa[1] = a_i[3];
                    dIa[2] = static_cast<T>(0);
                    dIa[3] = a_i[1];
                    dIa[4] =  - a_i[0];
                    dIa[5] = static_cast<T>(0);
                    break;
                }
                case 4: {
                    dIv[0] = v_i[0];
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    dIa[0] = a_i[0];
                    dIa[1] = static_cast<T>(0);
                    dIa[2] = static_cast<T>(0);
                    dIa[3] = static_cast<T>(0);
                    dIa[4] = static_cast<T>(0);
                    dIa[5] = static_cast<T>(0);
                    break;
                }
                case 5: {
                    dIv[0] = v_i[1];
                    dIv[1] = v_i[0];
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    dIa[0] = a_i[1];
                    dIa[1] = a_i[0];
                    dIa[2] = static_cast<T>(0);
                    dIa[3] = static_cast<T>(0);
                    dIa[4] = static_cast<T>(0);
                    dIa[5] = static_cast<T>(0);
                    break;
                }
                case 6: {
                    dIv[0] = v_i[2];
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = v_i[0];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    dIa[0] = a_i[2];
                    dIa[1] = static_cast<T>(0);
                    dIa[2] = a_i[0];
                    dIa[3] = static_cast<T>(0);
                    dIa[4] = static_cast<T>(0);
                    dIa[5] = static_cast<T>(0);
                    break;
                }
                case 7: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = v_i[1];
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    dIa[0] = static_cast<T>(0);
                    dIa[1] = a_i[1];
                    dIa[2] = static_cast<T>(0);
                    dIa[3] = static_cast<T>(0);
                    dIa[4] = static_cast<T>(0);
                    dIa[5] = static_cast<T>(0);
                    break;
                }
                case 8: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = v_i[2];
                    dIv[2] = v_i[1];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    dIa[0] = static_cast<T>(0);
                    dIa[1] = a_i[2];
                    dIa[2] = a_i[1];
                    dIa[3] = static_cast<T>(0);
                    dIa[4] = static_cast<T>(0);
                    dIa[5] = static_cast<T>(0);
                    break;
                }
                case 9: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = v_i[2];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    dIa[0] = static_cast<T>(0);
                    dIa[1] = static_cast<T>(0);
                    dIa[2] = a_i[2];
                    dIa[3] = static_cast<T>(0);
                    dIa[4] = static_cast<T>(0);
                    dIa[5] = static_cast<T>(0);
                    break;
                }
                default: { for (int r=0;r<6;r++){dIv[r]=static_cast<T>(0); dIa[r]=static_cast<T>(0);} }
            }
            fx_times_v<T>(crfv, v_i, dIv);
            for (int r=0;r<6;r++){ f[r] = dIa[r] + crfv[r]; }
            switch (link_i) {
                case 0: {
                    s_Y[0*70 + col] += f[2];
                    break;
                }
                case 1: {
                    s_Y[1*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[36 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[0*70 + col] += f[2];
                    break;
                }
                case 2: {
                    s_Y[2*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[72 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[1*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[36 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[0*70 + col] += f[2];
                    break;
                }
                case 3: {
                    s_Y[3*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[108 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[2*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[72 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[1*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[36 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[0*70 + col] += f[2];
                    break;
                }
                case 4: {
                    s_Y[4*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[144 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[3*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[108 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[2*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[72 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[1*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[36 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[0*70 + col] += f[2];
                    break;
                }
                case 5: {
                    s_Y[5*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[180 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[4*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[144 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[3*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[108 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[2*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[72 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[1*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[36 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[0*70 + col] += f[2];
                    break;
                }
                case 6: {
                    s_Y[6*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[216 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[5*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[180 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[4*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[144 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[3*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[108 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[2*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[72 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[1*70 + col] += f[2];
                    { T ft[6];
                      for (int r=0;r<6;r++){ T acc=static_cast<T>(0); for(int c=0;c<6;c++){ acc += s_XImats[36 + 6*r + c] * f[c]; } ft[r]=acc; }
                      for (int r=0;r<6;r++){f[r]=ft[r];} }
                    s_Y[0*70 + col] += f[2];
                    break;
                }
            }
        }
        __syncthreads();
    }

    /**
     * Compute the joint-torque regressor Y (tau = Y . pi)
     *
     * @param s_Y is the output regressor (nv x 10*NUM_BODIES)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_qdd is the vector of joint accelerations
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     */
    template <typename T>
    __device__
    void inverse_dynamics_regressor_device(T *s_Y, const T *s_q, const T *s_qd, const T *s_qdd, const robotModel<T> *d_robotModel, const T gravity) {
        // GRID shared arena layout
        //   T s_vaf[126]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(672, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        inverse_dynamics_regressor_inner<T>(s_Y, s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, gravity);
    }

    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    /**
     * Compute the joint-torque regressor
     *
     * @param d_Y is the output regressor, row-major nv x 10*NUM_BODIES = 490
     * @param d_q_qd_qdd is the vector of joint positions, velocities, accelerations (q|qd|qdd)
     * @param stride_q_qd_qdd is the stride between each (q, qd, qdd) triple
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     */
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void inverse_dynamics_regressor_kernel(T *d_Y, unsigned char *d_workspace, const T *d_q_qd_qdd, const int stride_q_qd_qdd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        constexpr bool REGRESSOR_Y_IN_SMEM = INVERSE_DYNAMICS_REGRESSOR_Y_IN_SMEM<RESOURCE_TIER>();
        constexpr int REGRESSOR_Y_SLOT = REGRESSOR_Y_IN_SMEM ? 490 : 0;
        // GRID shared arena layout
        //   T s_q_qd_qdd[21]
        //   T s_vaf[126]
        //   T s_Y[REGRESSOR_Y_SLOT]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(21);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_Y = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(REGRESSOR_Y_SLOT);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(static_cast<size_t>(0 + 21 + 126 + REGRESSOR_Y_SLOT + 504 + 42), 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        if constexpr (REGRESSOR_Y_IN_SMEM) { (void)d_workspace; }
        T *s_q = s_q_qd_qdd; T *s_qd = &s_q_qd_qdd[7]; T *s_qdd = &s_q_qd_qdd[14];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            // load to shared mem
            const T *d_q_qd_qdd_k = &d_q_qd_qdd[k*stride_q_qd_qdd];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_qdd[ind] = d_q_qd_qdd_k[ind];
            }
            __syncthreads();
            if constexpr (!REGRESSOR_Y_IN_SMEM) {
                s_Y = reinterpret_cast<T *>(&d_workspace[k*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
            }
            // compute
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            inverse_dynamics_regressor_inner<T>(s_Y, s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, gravity);
            __syncthreads();
            // save down to global
            T *d_Y_k = &d_Y[k*490];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 490; ind += blockDim.x*blockDim.y){
                d_Y_k[ind] = s_Y[ind];
            }
            __syncthreads();
        }
    }

    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    /**
     * Compute the joint-torque regressor
     *
     * @param d_Y is the output regressor, row-major nv x 10*NUM_BODIES = 490
     * @param d_q_qd_qdd is the vector of joint positions, velocities, accelerations (q|qd|qdd)
     * @param stride_q_qd_qdd is the stride between each (q, qd, qdd) triple
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     */
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void inverse_dynamics_regressor_kernel_single_timing(T *d_Y, unsigned char *d_workspace, const T *d_q_qd_qdd, const int stride_q_qd_qdd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        constexpr bool REGRESSOR_Y_IN_SMEM = INVERSE_DYNAMICS_REGRESSOR_Y_IN_SMEM<RESOURCE_TIER>();
        constexpr int REGRESSOR_Y_SLOT = REGRESSOR_Y_IN_SMEM ? 490 : 0;
        // GRID shared arena layout
        //   T s_q_qd_qdd[21]
        //   T s_vaf[126]
        //   T s_Y[REGRESSOR_Y_SLOT]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(21);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_Y = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(REGRESSOR_Y_SLOT);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(static_cast<size_t>(0 + 21 + 126 + REGRESSOR_Y_SLOT + 504 + 42), 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        if constexpr (REGRESSOR_Y_IN_SMEM) { (void)d_workspace; }
        T *s_q = s_q_qd_qdd; T *s_qd = &s_q_qd_qdd[7]; T *s_qdd = &s_q_qd_qdd[14];
        // load to shared mem
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
            s_q_qd_qdd[ind] = d_q_qd_qdd[ind];
        }
        __syncthreads();
        if constexpr (!REGRESSOR_Y_IN_SMEM) {
            s_Y = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
        }
        // compute with NUM_TIMESTEPS as NUM_REPS for timing
        for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            inverse_dynamics_regressor_inner<T>(s_Y, s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, gravity);
            __syncthreads();
        }
        // save down to global
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 490; ind += blockDim.x*blockDim.y){
            d_Y[ind] = s_Y[ind];
        }
        __syncthreads();
    }

    /**
     * Compute the joint-torque regressor Y (tau = Y . pi)
     *
     * @param hd_data is the packaged input and output pointers (q/qd/qdd inputs; output regressor written to hd_data->d_Y, 10*NB*nv*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void inverse_dynamics_regressor(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "inverse_dynamics_regressor requires all-data or dynamics gridData");
        int stride_q_qd_qdd = Q_QD_U_STRIDE;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_qdd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        if (!INVERSE_DYNAMICS_REGRESSOR_Y_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("inverse_dynamics_regressor", INVERSE_DYNAMICS_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        inverse_dynamics_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_Y,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,d_robotModel,gravity,num_timesteps);
        // finally transfer the result back into the gridData host buffer (hd_data->d_Y -> hd_data->h_Y)
        gpuErrchk(cudaMemcpy(hd_data->h_Y,hd_data->d_Y,num_timesteps*490*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the joint-torque regressor Y (tau = Y . pi)
     *
     * @param hd_data is the packaged input and output pointers (q/qd/qdd inputs; output regressor written to hd_data->d_Y, 10*NB*nv*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void inverse_dynamics_regressor_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "inverse_dynamics_regressor requires all-data or dynamics gridData");
        int stride_q_qd_qdd = Q_QD_U_STRIDE;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_qdd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        if (!INVERSE_DYNAMICS_REGRESSOR_Y_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()));}
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("inverse_dynamics_regressor", INVERSE_DYNAMICS_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        inverse_dynamics_regressor_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_Y,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back into the gridData host buffer (hd_data->d_Y -> hd_data->h_Y)
        gpuErrchk(cudaMemcpy(hd_data->h_Y,hd_data->d_Y,490*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call INVERSE_DYNAMICS_REGRESSOR %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the joint-torque regressor Y (tau = Y . pi)
     *
     * @param hd_data is the packaged input and output pointers (q/qd/qdd inputs; output regressor written to hd_data->d_Y, 10*NB*nv*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void inverse_dynamics_regressor_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "inverse_dynamics_regressor requires all-data or dynamics gridData");
        int stride_q_qd_qdd = Q_QD_U_STRIDE;
        // then call the kernel
        if (!INVERSE_DYNAMICS_REGRESSOR_Y_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("inverse_dynamics_regressor", INVERSE_DYNAMICS_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        inverse_dynamics_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_Y,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
    }

    /**
     * Compute the kinetic-energy regressor y_KE (KE = y_KE . pi)
     *
     * Notes:
     *   Assumes the XI matricies have already been updated for the given q
     *   KE = y_KE . pi ; y_KE[10*i+k] = 1/2 v_i^T (dI_k) v_i  (pi_i = [m, m*c(3), I_O(6)])
     *
     * @param s_y_ke is the output kinetic-energy regressor, length 10*NUM_BODIES = 70
     * @param s_vaf is scratch of size 18*NUM_JOINTS = 126 (RNEA v|a|f; only v consumed)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_temp is helper shared memory of size 42
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param gravity is the gravity constant (unused; KE is gravity-independent)
     */
    template <typename T>
    __device__
    void kinetic_energy_regressor_inner(T *s_y_ke, T *s_vaf, const T *s_q, const T *s_qd, T *s_XImats, int *s_topology_helpers, T *s_temp, const T gravity) {
        (void)gravity;
        // forward RNEA sweep: populate s_vaf v (reuse RNEA vaf inner; qdd irrelevant to v)
        inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
        __syncthreads();
        // y_KE[10*i+k] = 1/2 v_i^T (dI_k) v_i over all 10*NUM_BODIES columns
        for(int col = threadIdx.x + threadIdx.y*blockDim.x; col < 70; col += blockDim.x*blockDim.y){
            int link_i = col / 10; int param_k = col % 10;
            const T *v_i = &s_vaf[6*link_i];
            T dIv[6];
            switch (param_k) {
                case 0: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = v_i[3];
                    dIv[4] = v_i[4];
                    dIv[5] = v_i[5];
                    break;
                }
                case 1: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] =  - v_i[5];
                    dIv[2] = v_i[4];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = v_i[2];
                    dIv[5] =  - v_i[1];
                    break;
                }
                case 2: {
                    dIv[0] = v_i[5];
                    dIv[1] = static_cast<T>(0);
                    dIv[2] =  - v_i[3];
                    dIv[3] =  - v_i[2];
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = v_i[0];
                    break;
                }
                case 3: {
                    dIv[0] =  - v_i[4];
                    dIv[1] = v_i[3];
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = v_i[1];
                    dIv[4] =  - v_i[0];
                    dIv[5] = static_cast<T>(0);
                    break;
                }
                case 4: {
                    dIv[0] = v_i[0];
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    break;
                }
                case 5: {
                    dIv[0] = v_i[1];
                    dIv[1] = v_i[0];
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    break;
                }
                case 6: {
                    dIv[0] = v_i[2];
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = v_i[0];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    break;
                }
                case 7: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = v_i[1];
                    dIv[2] = static_cast<T>(0);
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    break;
                }
                case 8: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = v_i[2];
                    dIv[2] = v_i[1];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    break;
                }
                case 9: {
                    dIv[0] = static_cast<T>(0);
                    dIv[1] = static_cast<T>(0);
                    dIv[2] = v_i[2];
                    dIv[3] = static_cast<T>(0);
                    dIv[4] = static_cast<T>(0);
                    dIv[5] = static_cast<T>(0);
                    break;
                }
                default: { for (int r=0;r<6;r++){dIv[r]=static_cast<T>(0);} }
            }
            T dot = static_cast<T>(0); for (int r=0;r<6;r++){ dot += v_i[r]*dIv[r]; }
            s_y_ke[col] = static_cast<T>(0.5) * dot;
        }
        __syncthreads();
    }

    /**
     * Compute the kinetic-energy regressor y_KE (KE = y_KE . pi)
     *
     * @param s_y_ke is the output kinetic-energy regressor (length 10*NUM_BODIES)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant (unused)
     */
    template <typename T>
    __device__
    void kinetic_energy_regressor_device(T *s_y_ke, const T *s_q, const T *s_qd, const robotModel<T> *d_robotModel, const T gravity) {
        // GRID shared arena layout
        //   T s_vaf[126]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(672, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        kinetic_energy_regressor_inner<T>(s_y_ke, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, gravity);
    }

    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    /**
     * Compute the kinetic-energy regressor
     *
     * @param d_y_ke is the output kinetic-energy regressor, length 10*NUM_BODIES = 70
     * @param d_q_qd is the vector of joint positions, velocities (q|qd)
     * @param stride_q_qd is the stride between each (q, qd) pair
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant (unused)
     * @param num_timesteps is the length of the trajectory points
     */
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void kinetic_energy_regressor_kernel(T *d_y_ke, const T *d_q_qd, const int stride_q_qd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q_qd[14]
        //   T s_y_ke[70]
        //   T s_vaf[126]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(14);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_y_ke = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(70);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(756, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            // load to shared mem
            const T *d_q_qd_k = &d_q_qd[k*stride_q_qd];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd_k[ind];
            }
            __syncthreads();
            // compute
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            kinetic_energy_regressor_inner<T>(s_y_ke, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, gravity);
            __syncthreads();
            // save down to global
            T *d_y_ke_k = &d_y_ke[k*70];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 70; ind += blockDim.x*blockDim.y){
                d_y_ke_k[ind] = s_y_ke[ind];
            }
            __syncthreads();
        }
    }

    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    /**
     * Compute the kinetic-energy regressor
     *
     * @param d_y_ke is the output kinetic-energy regressor, length 10*NUM_BODIES = 70
     * @param d_q_qd is the vector of joint positions, velocities (q|qd)
     * @param stride_q_qd is the stride between each (q, qd) pair
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant (unused)
     * @param num_timesteps is the length of the trajectory points
     */
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void kinetic_energy_regressor_kernel_single_timing(T *d_y_ke, const T *d_q_qd, const int stride_q_qd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q_qd[14]
        //   T s_y_ke[70]
        //   T s_vaf[126]
        //   T s_XImats[504]
        //   T s_temp[42]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(14);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_y_ke = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(70);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(126);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(756, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
        // load to shared mem
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
            s_q_qd[ind] = d_q_qd[ind];
        }
        __syncthreads();
        // compute with NUM_TIMESTEPS as NUM_REPS for timing
        for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            kinetic_energy_regressor_inner<T>(s_y_ke, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, gravity);
            __syncthreads();
        }
        // save down to global
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 70; ind += blockDim.x*blockDim.y){
            d_y_ke[ind] = s_y_ke[ind];
        }
        __syncthreads();
    }

    /**
     * Compute the kinetic-energy regressor y_KE (KE = y_KE . pi)
     *
     * @param hd_data is the packaged input and output pointers (q/qd inputs; output written to hd_data->d_ke_regressor, 10*NB*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant (unused)
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void kinetic_energy_regressor(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "kinetic_energy_regressor requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("kinetic_energy_regressor", KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()));
        if (USE_COMPRESSED_MEM) {kinetic_energy_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_ke_regressor,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {kinetic_energy_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_ke_regressor,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        // finally transfer the result back into the gridData host buffer (hd_data->d_ke_regressor -> hd_data->h_ke_regressor)
        gpuErrchk(cudaMemcpy(hd_data->h_ke_regressor,hd_data->d_ke_regressor,num_timesteps*70*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the kinetic-energy regressor y_KE (KE = y_KE . pi)
     *
     * @param hd_data is the packaged input and output pointers (q/qd inputs; output written to hd_data->d_ke_regressor, 10*NB*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant (unused)
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void kinetic_energy_regressor_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "kinetic_energy_regressor requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("kinetic_energy_regressor", KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        if (USE_COMPRESSED_MEM) {kinetic_energy_regressor_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_ke_regressor,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {kinetic_energy_regressor_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_ke_regressor,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back into the gridData host buffer (hd_data->d_ke_regressor -> hd_data->h_ke_regressor)
        gpuErrchk(cudaMemcpy(hd_data->h_ke_regressor,hd_data->d_ke_regressor,70*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call KINETIC_ENERGY_REGRESSOR %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the kinetic-energy regressor y_KE (KE = y_KE . pi)
     *
     * @param hd_data is the packaged input and output pointers (q/qd inputs; output written to hd_data->d_ke_regressor, 10*NB*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant (unused)
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void kinetic_energy_regressor_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "kinetic_energy_regressor requires all-data or dynamics gridData");
        int stride_q_qd = USE_COMPRESSED_MEM ? 2*NUM_JOINTS : 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("kinetic_energy_regressor", KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()));
        if (USE_COMPRESSED_MEM) {kinetic_energy_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_ke_regressor,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {kinetic_energy_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,KINETIC_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_ke_regressor,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
    }

    /**
     * Compute the potential-energy regressor y_PE (PE = y_PE . pi)
     *
     * Notes:
     *   Assumes the homogeneous transforms s_Xhom have been updated for the given q
     *   PE = y_PE . pi ; per body i only the mass + 3 first-moment cols are nonzero:
     *     y[10i+0] = -(g . p_i) ; y[10i+1:4] = -(R_i^T g) ; inertia cols = 0
     *
     * @param s_y_pe is the output potential-energy regressor, length 10*NUM_BODIES = 70
     * @param s_q is the vector of joint positions (unused; q is baked into s_Xhom)
     * @param s_Xhom is the per-joint LOCAL homogeneous transforms (mimic-aware)
     * @param d_robotModel is the GPU model helpers (unused; PE needs only kinematics)
     * @param s_temp is scratch of size 112
     * @param gravity is the gravity constant (g = [0,0,gravity])
     */
    template <typename T>
    __device__
    void potential_energy_regressor_inner(T *s_y_pe, const T *s_q, const T *s_Xhom, const robotModel<T> *d_robotModel, T *s_temp, const T gravity) {
        (void)s_q; (void)d_robotModel;
        T *s_Xworld = s_temp;   // 16 * NUM_JOINTS world homogeneous transforms
        // Step 1: world homogeneous transforms (chain-up of local s_Xhom)
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            const int jid = 0; const int par = -1;
            if (par == -1) { s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele]; }
            else { s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]); }
        }
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            const int jid = 1; const int par = 0;
            if (par == -1) { s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele]; }
            else { s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]); }
        }
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            const int jid = 2; const int par = 1;
            if (par == -1) { s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele]; }
            else { s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]); }
        }
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            const int jid = 3; const int par = 2;
            if (par == -1) { s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele]; }
            else { s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]); }
        }
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            const int jid = 4; const int par = 3;
            if (par == -1) { s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele]; }
            else { s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]); }
        }
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            const int jid = 5; const int par = 4;
            if (par == -1) { s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele]; }
            else { s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]); }
        }
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            const int jid = 6; const int par = 5;
            if (par == -1) { s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele]; }
            else { s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]); }
        }
        __syncthreads();
        // Step 2: zero all cols then fill the 4 nonzero cols per body
        for(int col = threadIdx.x + threadIdx.y*blockDim.x; col < 70; col += blockDim.x*blockDim.y){
            int link_i = col / 10; int param_k = col % 10;
            const T *Xw = &s_Xworld[16*link_i];
            if (param_k == 0) { s_y_pe[col] = -gravity * Xw[14]; }
            else if (param_k <= 3) { s_y_pe[col] = -gravity * Xw[2 + 4*(param_k-1)]; }
            else { s_y_pe[col] = static_cast<T>(0); }
        }
        __syncthreads();
    }

    /**
     * Compute the potential-energy regressor y_PE (PE = y_PE . pi)
     *
     * @param s_y_pe is the output potential-energy regressor (length 10*NUM_BODIES)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     */
    template <typename T>
    __device__
    void potential_energy_regressor_device(T *s_y_pe, const T *s_q, const robotModel<T> *d_robotModel, const T gravity) {
        // GRID shared arena layout
        //   T s_XmatsHom[144]
        //   T s_temp[112]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(144);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(112);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(256, 0, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        potential_energy_regressor_inner<T>(s_y_pe, s_q, s_XmatsHom, d_robotModel, s_temp, gravity);
        __syncthreads();
    }

    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    /**
     * Compute the potential-energy regressor
     *
     * @param d_y_pe is the output potential-energy regressor, length 10*NUM_BODIES = 70
     * @param d_q is the vector of joint positions
     * @param stride_q is the stride between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     */
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void potential_energy_regressor_kernel(T *d_y_pe, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q[7]
        //   T s_y_pe[70]
        //   T s_XmatsHom[144]
        //   T s_temp[112]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_y_pe = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(70);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(144);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(112);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(333, 0, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            // load to shared mem
            const T *d_q_k = &d_q[k*stride_q];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q_k[ind];
            }
            __syncthreads();
            // compute
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            potential_energy_regressor_inner<T>(s_y_pe, s_q, s_XmatsHom, d_robotModel, s_temp, gravity);
            __syncthreads();
            // save down to global
            T *d_y_pe_k = &d_y_pe[k*70];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 70; ind += blockDim.x*blockDim.y){
                d_y_pe_k[ind] = s_y_pe[ind];
            }
            __syncthreads();
        }
    }

    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    /**
     * Compute the potential-energy regressor
     *
     * @param d_y_pe is the output potential-energy regressor, length 10*NUM_BODIES = 70
     * @param d_q is the vector of joint positions
     * @param stride_q is the stride between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     */
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void potential_energy_regressor_kernel_single_timing(T *d_y_pe, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q[7]
        //   T s_y_pe[70]
        //   T s_XmatsHom[144]
        //   T s_temp[112]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_y_pe = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(70);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(144);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(112);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(333, 0, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        // load to shared mem
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
            s_q[ind] = d_q[ind];
        }
        __syncthreads();
        // compute with NUM_TIMESTEPS as NUM_REPS for timing
        for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            potential_energy_regressor_inner<T>(s_y_pe, s_q, s_XmatsHom, d_robotModel, s_temp, gravity);
            __syncthreads();
        }
        // save down to global
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 70; ind += blockDim.x*blockDim.y){
            d_y_pe[ind] = s_y_pe[ind];
        }
        __syncthreads();
    }

    /**
     * Compute the potential-energy regressor y_PE (PE = y_PE . pi)
     *
     * @param hd_data is the packaged input and output pointers (q input; output written to hd_data->d_pe_regressor, 10*NB*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void potential_energy_regressor(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "potential_energy_regressor requires all-data or kinematics gridData");
        // start code with memory transfer
        int stride_q = NUM_JOINTS;
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("potential_energy_regressor", POTENTIAL_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()));
        potential_energy_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,POTENTIAL_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_pe_regressor,hd_data->d_q,stride_q,d_robotModel,gravity,num_timesteps);
        // finally transfer the result back into the gridData host buffer (hd_data->d_pe_regressor -> hd_data->h_pe_regressor)
        gpuErrchk(cudaMemcpy(hd_data->h_pe_regressor,hd_data->d_pe_regressor,num_timesteps*70*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the potential-energy regressor y_PE (PE = y_PE . pi)
     *
     * @param hd_data is the packaged input and output pointers (q input; output written to hd_data->d_pe_regressor, 10*NB*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void potential_energy_regressor_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "potential_energy_regressor requires all-data or kinematics gridData");
        // start code with memory transfer
        int stride_q = NUM_JOINTS;
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("potential_energy_regressor", POTENTIAL_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        potential_energy_regressor_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,POTENTIAL_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_pe_regressor,hd_data->d_q,stride_q,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back into the gridData host buffer (hd_data->d_pe_regressor -> hd_data->h_pe_regressor)
        gpuErrchk(cudaMemcpy(hd_data->h_pe_regressor,hd_data->d_pe_regressor,70*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call POTENTIAL_ENERGY_REGRESSOR %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the potential-energy regressor y_PE (PE = y_PE . pi)
     *
     * @param hd_data is the packaged input and output pointers (q input; output written to hd_data->d_pe_regressor, 10*NB*num_timesteps floats)
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     * @param streams are pointers to CUDA streams for async memory transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void potential_energy_regressor_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "potential_energy_regressor requires all-data or kinematics gridData");
        int stride_q = NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("potential_energy_regressor", POTENTIAL_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()));
        potential_energy_regressor_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,POTENTIAL_ENERGY_REGRESSOR_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_pe_regressor,hd_data->d_q,stride_q,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
    }

    /**
     * Compute the inverse of the mass matrix
     *
     * Notes:
     *   CALLER CONTRACT (direct *_inner callers): s_XImats must ALREADY be populated for the current s_q (READ-only here) via load_update_XImats_helpers(...) + __syncthreads(), and s_temp MUST be MINV_INNER_SMEM_BYTES<T, F_IN_SMEM>() bytes -- at F_IN_SMEM=true the 6*NV*NV F-band lives in the TAIL of s_temp (d_workspace=0/nullptr does NOT mean the band is free). Under-populating XImats or under-sizing s_temp reads never-written shared -> NaN (race-clean, DoF-specific since the band scales as 6*NV*NV). Prefer minv_device, which handles both.
     *   Outputs a SYMMETRIC_UPPER triangular matrix for Minv
     *   Inner-controlled placement: F_IN_SMEM selects where the 6*NV*NV F-region lives.
     *     true  -> tail of s_temp (shared; fastest, default).  false -> d_workspace (global).
     *   The choice is made at the top of this fn so the caller just sizes both arenas from
     *   the MINV_INNER_*_BYTES constants and hands both pointers in. Codegen maps each
     *   RESOURCE_TIER to an F_IN_SMEM value per robot (MINV_F_IN_SMEM<TIER>()).
     *
     * @param s_Minv is a pointer to memory for the final result
     * @param s_q is the vector of joint positions
     * @param s_temp is the (shared) scratch; size MINV_INNER_SMEM_BYTES<T, F_IN_SMEM>() (= 373 always, plus the 294-float F-region when F_IN_SMEM)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_workspace is the global scratch; size MINV_INNER_WORKSPACE_BYTES<T, F_IN_SMEM>() (= 294 when !F_IN_SMEM, else 0). Pass nullptr when F_IN_SMEM
     */
    template <typename T, bool F_IN_SMEM = true>
    __device__ __forceinline__
    void minv_inner(T *s_Minv, const T *s_q, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace) {
        unsigned char *s_linalg_smem = nullptr;
        T *s_F;
        if constexpr (F_IN_SMEM) { s_F = &s_temp[373]; (void)d_workspace; }
        else { s_F = d_workspace; }
        // T *s_F (param) [size 6*NV*NV]; T *s_IA = &s_temp[0]; T *s_U = &s_temp[252]; T *s_Dinv = &s_temp[294]; T *s_Ia = &s_temp[301]; T *s_IaTemp = &s_temp[337];
        // Initialize IA = I
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 252; ind += blockDim.x*blockDim.y){
            s_temp[0 + ind] = s_XImats[252 + ind];
        }
        // Zero Minv and F
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 343; ind += blockDim.x*blockDim.y){
            if(ind < 294){s_F[0 + ind] = static_cast<T>(0);}
            else{s_Minv[ind - 294] = static_cast<T>(0);}
        }
        __syncthreads();
        //
        // Backward Pass
        //
        // backward pass updates where bfs_level is 6
        //     joints are: A7
        //     links are: L7
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_temp[252 + 36 + row] = (1) * s_temp[0 + 6*36 + 6*2 + row];
            if(row == 2){
                s_temp[294 + 6] = static_cast<T>(1)/((1) * s_temp[252 + 36 + 2]);
                s_Minv[8 * 6] = s_temp[294 + 6];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1; ind += blockDim.x*blockDim.y){
            s_Minv[42 + 6] -= s_temp[294 + 6] * (1) * s_F[0 + 42*6 + 36 + 2];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 42*6 + 36 + row] += s_temp[252 + 6*6 + row] * s_Minv[42 + 6];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_temp[301 + ind] = s_temp[216 + ind] - (s_temp[288 + row] * s_temp[300] * s_temp[288 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 42; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            T *src = &s_F[0 + 42*6 + 6*6]; T *dst = &s_F[0 + 42*5 + 6*6];
            // adjust for temp comps
            if (col >= 1) {
                col -= 1; src = &s_temp[301 + 6*col]; dst = &s_temp[337 + 6*col];
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*6 + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[337], &s_XImats[216], &s_temp[180], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 5
        //     joints are: A6
        //     links are: L6
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_temp[252 + 30 + row] = (1) * s_temp[0 + 6*30 + 6*2 + row];
            if(row == 2){
                s_temp[294 + 5] = static_cast<T>(1)/((1) * s_temp[252 + 30 + 2]);
                s_Minv[8 * 5] = s_temp[294 + 5];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 2; ind += blockDim.x*blockDim.y){
            int jid_subtree6 = 6*(5 + ind); int jid_subtreeN = 7*(5 + ind);
            s_Minv[jid_subtreeN + 5] -= s_temp[294 + 5] * (1) * s_F[0 + 42*5 + jid_subtree6 + 2];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 42*5 + jid_subtree6 + row] += s_temp[252 + 6*5 + row] * s_Minv[jid_subtreeN + 5];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_temp[301 + ind] = s_temp[180 + ind] - (s_temp[282 + row] * s_temp[299] * s_temp[282 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 48; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            T *src = &s_F[0 + 42*5 + 6*(5 + col)]; T *dst = &s_F[0 + 42*4 + 6*(5 + col)];
            // adjust for temp comps
            if (col >= 2) {
                col -= 2; src = &s_temp[301 + 6*col]; dst = &s_temp[337 + 6*col];
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*5 + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[337], &s_XImats[180], &s_temp[144], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 4
        //     joints are: A5
        //     links are: L5
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_temp[252 + 24 + row] = (1) * s_temp[0 + 6*24 + 6*2 + row];
            if(row == 2){
                s_temp[294 + 4] = static_cast<T>(1)/((1) * s_temp[252 + 24 + 2]);
                s_Minv[8 * 4] = s_temp[294 + 4];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 3; ind += blockDim.x*blockDim.y){
            int jid_subtree6 = 6*(4 + ind); int jid_subtreeN = 7*(4 + ind);
            s_Minv[jid_subtreeN + 4] -= s_temp[294 + 4] * (1) * s_F[0 + 42*4 + jid_subtree6 + 2];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 42*4 + jid_subtree6 + row] += s_temp[252 + 6*4 + row] * s_Minv[jid_subtreeN + 4];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_temp[301 + ind] = s_temp[144 + ind] - (s_temp[276 + row] * s_temp[298] * s_temp[276 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 54; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            T *src = &s_F[0 + 42*4 + 6*(4 + col)]; T *dst = &s_F[0 + 42*3 + 6*(4 + col)];
            // adjust for temp comps
            if (col >= 3) {
                col -= 3; src = &s_temp[301 + 6*col]; dst = &s_temp[337 + 6*col];
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*4 + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[337], &s_XImats[144], &s_temp[108], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 3
        //     joints are: A4
        //     links are: L4
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_temp[252 + 18 + row] = (1) * s_temp[0 + 6*18 + 6*2 + row];
            if(row == 2){
                s_temp[294 + 3] = static_cast<T>(1)/((1) * s_temp[252 + 18 + 2]);
                s_Minv[8 * 3] = s_temp[294 + 3];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 4; ind += blockDim.x*blockDim.y){
            int jid_subtree6 = 6*(3 + ind); int jid_subtreeN = 7*(3 + ind);
            s_Minv[jid_subtreeN + 3] -= s_temp[294 + 3] * (1) * s_F[0 + 42*3 + jid_subtree6 + 2];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 42*3 + jid_subtree6 + row] += s_temp[252 + 6*3 + row] * s_Minv[jid_subtreeN + 3];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_temp[301 + ind] = s_temp[108 + ind] - (s_temp[270 + row] * s_temp[297] * s_temp[270 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 60; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            T *src = &s_F[0 + 42*3 + 6*(3 + col)]; T *dst = &s_F[0 + 42*2 + 6*(3 + col)];
            // adjust for temp comps
            if (col >= 4) {
                col -= 4; src = &s_temp[301 + 6*col]; dst = &s_temp[337 + 6*col];
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*3 + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[337], &s_XImats[108], &s_temp[72], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 2
        //     joints are: A3
        //     links are: L3
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_temp[252 + 12 + row] = (1) * s_temp[0 + 6*12 + 6*2 + row];
            if(row == 2){
                s_temp[294 + 2] = static_cast<T>(1)/((1) * s_temp[252 + 12 + 2]);
                s_Minv[8 * 2] = s_temp[294 + 2];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5; ind += blockDim.x*blockDim.y){
            int jid_subtree6 = 6*(2 + ind); int jid_subtreeN = 7*(2 + ind);
            s_Minv[jid_subtreeN + 2] -= s_temp[294 + 2] * (1) * s_F[0 + 42*2 + jid_subtree6 + 2];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 42*2 + jid_subtree6 + row] += s_temp[252 + 6*2 + row] * s_Minv[jid_subtreeN + 2];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_temp[301 + ind] = s_temp[72 + ind] - (s_temp[264 + row] * s_temp[296] * s_temp[264 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 66; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            T *src = &s_F[0 + 42*2 + 6*(2 + col)]; T *dst = &s_F[0 + 42*1 + 6*(2 + col)];
            // adjust for temp comps
            if (col >= 5) {
                col -= 5; src = &s_temp[301 + 6*col]; dst = &s_temp[337 + 6*col];
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*2 + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[337], &s_XImats[72], &s_temp[36], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 1
        //     joints are: A2
        //     links are: L2
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_temp[252 + 6 + row] = (1) * s_temp[0 + 6*6 + 6*2 + row];
            if(row == 2){
                s_temp[294 + 1] = static_cast<T>(1)/((1) * s_temp[252 + 6 + 2]);
                s_Minv[8 * 1] = s_temp[294 + 1];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
            int jid_subtree6 = 6*(1 + ind); int jid_subtreeN = 7*(1 + ind);
            s_Minv[jid_subtreeN + 1] -= s_temp[294 + 1] * (1) * s_F[0 + 42*1 + jid_subtree6 + 2];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 42*1 + jid_subtree6 + row] += s_temp[252 + 6*1 + row] * s_Minv[jid_subtreeN + 1];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_temp[301 + ind] = s_temp[36 + ind] - (s_temp[258 + row] * s_temp[295] * s_temp[258 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 72; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            T *src = &s_F[0 + 42*1 + 6*(1 + col)]; T *dst = &s_F[0 + 42*0 + 6*(1 + col)];
            // adjust for temp comps
            if (col >= 6) {
                col -= 6; src = &s_temp[301 + 6*col]; dst = &s_temp[337 + 6*col];
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*1 + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[337], &s_XImats[36], &s_temp[0], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 0
        //     joints are: A1
        //     links are: L1
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_temp[252 + 0 + row] = (1) * s_temp[0 + 6*0 + 6*2 + row];
            if(row == 2){
                s_temp[294 + 0] = static_cast<T>(1)/((1) * s_temp[252 + 0 + 2]);
                s_Minv[8 * 0] = s_temp[294 + 0];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
            int jid_subtree6 = 6*(0 + ind); int jid_subtreeN = 7*(0 + ind);
            s_Minv[jid_subtreeN + 0] -= s_temp[294 + 0] * (1) * s_F[0 + 42*0 + jid_subtree6 + 2];
        }
        __syncthreads();
        //
        // Forward Pass
        //   Note that due to the i: operation we need to go serially over all n
        //
        // forward pass for jid: 0
        // F[i,:,i:] = S * Minv[i,i:] as parent is base so rest is skipped
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 42; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_F[0 + ind] = (row == 2) * (1) * s_Minv[0 + 7 * col];
        }
        __syncthreads();
        // forward pass for jid: 1
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 6; c += blockDim.x*blockDim.y){
            int col_ind = c + 1;
            T *s_Fcol = &s_F[42 + 6*col_ind];
            T *s_Fpcol = &s_F[0 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[36 + row], s_Fpcol);
            }
            s_Minv[7 * col_ind + 1] -= s_temp[295] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[258]);
            s_Fcol[2] += (1) * s_Minv[7 * col_ind + 1];
        }
        __syncthreads();
        // forward pass for jid: 2
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 5; c += blockDim.x*blockDim.y){
            int col_ind = c + 2;
            T *s_Fcol = &s_F[84 + 6*col_ind];
            T *s_Fpcol = &s_F[42 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[72 + row], s_Fpcol);
            }
            s_Minv[7 * col_ind + 2] -= s_temp[296] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[264]);
            s_Fcol[2] += (1) * s_Minv[7 * col_ind + 2];
        }
        __syncthreads();
        // forward pass for jid: 3
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 4; c += blockDim.x*blockDim.y){
            int col_ind = c + 3;
            T *s_Fcol = &s_F[126 + 6*col_ind];
            T *s_Fpcol = &s_F[84 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[108 + row], s_Fpcol);
            }
            s_Minv[7 * col_ind + 3] -= s_temp[297] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[270]);
            s_Fcol[2] += (1) * s_Minv[7 * col_ind + 3];
        }
        __syncthreads();
        // forward pass for jid: 4
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 3; c += blockDim.x*blockDim.y){
            int col_ind = c + 4;
            T *s_Fcol = &s_F[168 + 6*col_ind];
            T *s_Fpcol = &s_F[126 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[144 + row], s_Fpcol);
            }
            s_Minv[7 * col_ind + 4] -= s_temp[298] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[276]);
            s_Fcol[2] += (1) * s_Minv[7 * col_ind + 4];
        }
        __syncthreads();
        // forward pass for jid: 5
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 2; c += blockDim.x*blockDim.y){
            int col_ind = c + 5;
            T *s_Fcol = &s_F[210 + 6*col_ind];
            T *s_Fpcol = &s_F[168 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[180 + row], s_Fpcol);
            }
            s_Minv[7 * col_ind + 5] -= s_temp[299] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[282]);
            s_Fcol[2] += (1) * s_Minv[7 * col_ind + 5];
        }
        __syncthreads();
        // forward pass for jid: 6
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 1; c += blockDim.x*blockDim.y){
            int col_ind = c + 6;
            T *s_Fcol = &s_F[252 + 6*col_ind];
            T *s_Fpcol = &s_F[210 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[216 + row], s_Fpcol);
            }
            s_Minv[7 * col_ind + 6] -= s_temp[300] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[288]);
        }
        __syncthreads();
    }

    /**
     * Compute the inverse of the mass matrix
     *
     * Notes:
     *   Outputs a SYMMETRIC_UPPER triangular matrix for Minv
     *
     * @param s_Minv is a pointer to memory for the final result
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     */
    template <typename T>
    __device__
    void minv_device(T *s_Minv, const T *s_q, const robotModel<T> *d_robotModel){
        // GRID shared arena layout
        //   T s_XImats[504]
        //   T s_temp[667]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(667);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(1171, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
    }

    /**
     * Compute the inverse of the mass matrix
     *
     * Notes:
     *   Outputs a SYMMETRIC_UPPER triangular matrix for Minv
     *
     * @param d_Minv is a pointer to memory for the final result
     * @param d_workspace is the L2-pinned global spill buffer (used when Minv-F overflows smem)
     * @param d_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void minv_kernel_single_timing(T *d_Minv, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS){
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_Minv[49]
            //   T s_XImats[504]
            //   T s_temp[667]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(667);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1227, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 7; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (7)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_Minv into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (7)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (7)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (7)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_Minv)[rep & 1023] = reinterpret_cast<const volatile T *>(s_Minv)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                d_Minv[ind] = s_Minv[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_Minv[49]
            //   T s_XImats[504]
            //   T s_temp[667]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(667);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1227, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 7; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (7)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_Minv into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (7)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (7)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (7)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_Minv)[rep & 1023] = reinterpret_cast<const volatile T *>(s_Minv)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                d_Minv[ind] = s_Minv[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_Minv[49]
            //   T s_XImats[504]
            //   T s_temp[373]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(373);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(933, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            T *minv_d_workspace = reinterpret_cast<T *>(&d_workspace[GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 7; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (7)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_Minv into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_Minv)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (7)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (7)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (7)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                minv_inner<T, false>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, minv_d_workspace);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_Minv)[rep & 1023] = reinterpret_cast<const volatile T *>(s_Minv)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                d_Minv[ind] = s_Minv[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Compute the inverse of the mass matrix
     *
     * Notes:
     *   Outputs a SYMMETRIC_UPPER triangular matrix for Minv
     *
     * @param d_Minv is a pointer to memory for the final result
     * @param d_workspace is the L2-pinned global spill buffer (used when Minv-F overflows smem)
     * @param d_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void minv_kernel(T *d_Minv, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS){
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_Minv[49]
            //   T s_XImats[504]
            //   T s_temp[667]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(667);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1227, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_k = &d_q[k*stride_q];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = d_q_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                __syncthreads();
                // save down to global
                T *d_Minv_k = &d_Minv[k*49];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                    d_Minv_k[ind] = s_Minv[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_Minv[49]
            //   T s_XImats[504]
            //   T s_temp[667]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(667);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1227, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_k = &d_q[k*stride_q];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = d_q_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                __syncthreads();
                // save down to global
                T *d_Minv_k = &d_Minv[k*49];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                    d_Minv_k[ind] = s_Minv[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q[7]
            //   T s_Minv[49]
            //   T s_XImats[504]
            //   T s_temp[373]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(373);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(933, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_k = &d_q[k*stride_q];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = d_q_k[ind];
                }
                __syncthreads();
                T *minv_d_workspace = reinterpret_cast<T *>(&d_workspace[k*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                minv_inner<T, false>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, minv_d_workspace);
                __syncthreads();
                // save down to global
                T *d_Minv_k = &d_Minv[k*49];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                    d_Minv_k[ind] = s_Minv[ind];
                }
                __syncthreads();
