                __syncthreads();
                // save down to global
                T *d_dc_du_k = &d_dc_du[k*98];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    d_dc_du_k[ind] = s_dc_du[ind];
                }
                __syncthreads();
            }
        }
    }

    /**
     * Computes the gradient of inverse dynamics
