        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_va[54 + row] += s_temp[516 + row];
        }
        __syncthreads();
        // qdd[k] = (u[k] - U[k].T*a[k])/d[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1; ind += blockDim.x*blockDim.y){
            int jid = 2;
            int jid6 = 6 * 2;
            T tempval = s_temp[97 * 7+jid] - dot_prod<T,6,1,1>(&s_temp[84*7+jid6], &s_va[6*7+jid6]);
            s_qdd[jid] = tempval / s_temp[96*7+jid];
        }
        __syncthreads();
        // a[k] += qdd[k]*S[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            int jid = 2;
            int jid6 = 6 * 2;
            T qdd_val = (row == 2) * (1) * (s_qdd[jid]);
            s_va[6*7+jid6+row] += qdd_val;
        }
        __syncthreads();
        // s_a, s_qdd where bfs_level is 3
        //     joints are: A4
        //     links are: L4
        // a[k] = X[k]*a[parent] + c[k]
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[108], &s_va[54], &s_va[60], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_va[60 + row] += s_temp[522 + row];
        }
        __syncthreads();
        // qdd[k] = (u[k] - U[k].T*a[k])/d[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1; ind += blockDim.x*blockDim.y){
            int jid = 3;
            int jid6 = 6 * 3;
            T tempval = s_temp[97 * 7+jid] - dot_prod<T,6,1,1>(&s_temp[84*7+jid6], &s_va[6*7+jid6]);
            s_qdd[jid] = tempval / s_temp[96*7+jid];
        }
        __syncthreads();
        // a[k] += qdd[k]*S[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            int jid = 3;
            int jid6 = 6 * 3;
            T qdd_val = (row == 2) * (1) * (s_qdd[jid]);
            s_va[6*7+jid6+row] += qdd_val;
        }
        __syncthreads();
        // s_a, s_qdd where bfs_level is 4
        //     joints are: A5
        //     links are: L5
        // a[k] = X[k]*a[parent] + c[k]
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[144], &s_va[60], &s_va[66], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_va[66 + row] += s_temp[528 + row];
        }
        __syncthreads();
        // qdd[k] = (u[k] - U[k].T*a[k])/d[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1; ind += blockDim.x*blockDim.y){
            int jid = 4;
            int jid6 = 6 * 4;
            T tempval = s_temp[97 * 7+jid] - dot_prod<T,6,1,1>(&s_temp[84*7+jid6], &s_va[6*7+jid6]);
            s_qdd[jid] = tempval / s_temp[96*7+jid];
        }
        __syncthreads();
        // a[k] += qdd[k]*S[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            int jid = 4;
            int jid6 = 6 * 4;
            T qdd_val = (row == 2) * (1) * (s_qdd[jid]);
            s_va[6*7+jid6+row] += qdd_val;
        }
        __syncthreads();
        // s_a, s_qdd where bfs_level is 5
        //     joints are: A6
        //     links are: L6
        // a[k] = X[k]*a[parent] + c[k]
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[180], &s_va[66], &s_va[72], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_va[72 + row] += s_temp[534 + row];
        }
        __syncthreads();
        // qdd[k] = (u[k] - U[k].T*a[k])/d[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1; ind += blockDim.x*blockDim.y){
            int jid = 5;
            int jid6 = 6 * 5;
            T tempval = s_temp[97 * 7+jid] - dot_prod<T,6,1,1>(&s_temp[84*7+jid6], &s_va[6*7+jid6]);
            s_qdd[jid] = tempval / s_temp[96*7+jid];
        }
        __syncthreads();
        // a[k] += qdd[k]*S[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            int jid = 5;
            int jid6 = 6 * 5;
            T qdd_val = (row == 2) * (1) * (s_qdd[jid]);
            s_va[6*7+jid6+row] += qdd_val;
        }
        __syncthreads();
        // s_a, s_qdd where bfs_level is 6
        //     joints are: A7
        //     links are: L7
        // a[k] = X[k]*a[parent] + c[k]
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[216], &s_va[72], &s_va[78], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        for(int row = threadIdx.x + threadIdx.y*blockDim.x; row < 6; row += blockDim.x*blockDim.y){
            s_va[78 + row] += s_temp[540 + row];
        }
        __syncthreads();
        // qdd[k] = (u[k] - U[k].T*a[k])/d[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1; ind += blockDim.x*blockDim.y){
            int jid = 6;
            int jid6 = 6 * 6;
            T tempval = s_temp[97 * 7+jid] - dot_prod<T,6,1,1>(&s_temp[84*7+jid6], &s_va[6*7+jid6]);
            s_qdd[jid] = tempval / s_temp[96*7+jid];
        }
        __syncthreads();
        // a[k] += qdd[k]*S[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            int jid = 6;
            int jid6 = 6 * 6;
            T qdd_val = (row == 2) * (1) * (s_qdd[jid]);
            s_va[6*7+jid6+row] += qdd_val;
        }
        __syncthreads();
    }

    /**
     * Compute the ABA (Articulated Body Algorithm)
     *
     * @param s_qdd is the vector of joint accelerations
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_tau is the vector of joint torques
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     */
    template <typename T>
    __device__
    void aba_device(T *s_qdd, const T *s_q, const T *s_qd, const T *s_tau, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity) {
        // GRID shared arena layout
        //   T s_va[84]
        //   T s_XImats[504]
        //   T s_temp[980]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_va = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(84);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(980);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(1568, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        aba_inner<T, true, true>(s_qdd, s_va, s_q, s_qd, s_tau, s_XImats, s_topology_helpers, s_temp, nullptr, d_f_ext, gravity);
    }

    /**
     * Compute the ABA (Articulated Body Algorithm)
     *
     * @param d_qdd is the vector of joint accelerations (output)
     * @param d_workspace is the L2-pinned global spill buffer (used at LITE/MINIMAL on h1_2-scale)
     * @param d_q_qd_tau is the vector of joint positions, velocities, torques
     * @param stride_q_qd is the stride between each q, qd
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void aba_kernel_single_timing(T *d_qdd, unsigned char *d_workspace, const T *d_q_qd_tau, const int stride_q_qd, T *d_f_ext, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_qdd[7]
            //   T s_q_qd_tau[21]
            //   T s_va[84]
            //   T s_XImats[504]
            //   T s_temp[980]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_tau = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_va = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(84);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(980);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1596, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_tau; T *s_qd = &s_q_qd_tau[7]; T *s_tau = &s_q_qd_tau[14];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_tau[ind] = d_q_qd_tau[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 21; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_tau)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[rep % (21)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_qdd into s_q_qd_tau (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 1) % (21)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 3) % (21)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                aba_inner<T, true, true>(s_qdd, s_va, s_q, s_qd, s_tau, s_XImats, s_topology_helpers, s_temp, nullptr, d_f_ext, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_qdd)[rep & 1023] = reinterpret_cast<const volatile T *>(s_qdd)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                d_qdd[ind] = s_qdd[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_qdd[7]
            //   T s_q_qd_tau[21]
            //   T s_va[84]
            //   T s_XImats[504]
            //   T s_temp[980]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_tau = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_va = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(84);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(980);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1596, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_tau; T *s_qd = &s_q_qd_tau[7]; T *s_tau = &s_q_qd_tau[14];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_tau[ind] = d_q_qd_tau[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 21; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_tau)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[rep % (21)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_qdd into s_q_qd_tau (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 1) % (21)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 3) % (21)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                aba_inner<T, true, true>(s_qdd, s_va, s_q, s_qd, s_tau, s_XImats, s_topology_helpers, s_temp, nullptr, d_f_ext, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_qdd)[rep & 1023] = reinterpret_cast<const volatile T *>(s_qdd)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                d_qdd[ind] = s_qdd[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_qdd[7]
            //   T s_q_qd_tau[21]
            //   T s_va[84]
            //   T s_XImats[504]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_tau = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_va = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(84);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            T *s_temp = nullptr;
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(616, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_tau; T *s_qd = &s_q_qd_tau[7]; T *s_tau = &s_q_qd_tau[14];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_tau[ind] = d_q_qd_tau[ind];
            }
            __syncthreads();
            T *aba_d_workspace = reinterpret_cast<T *>(d_workspace);
            s_temp = aba_d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 21; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_tau)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[rep % (21)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_qdd into s_q_qd_tau (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_qdd)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 1) % (21)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_tau)[(rep + 3) % (21)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                aba_inner<T, false, true>(s_qdd, s_va, s_q, s_qd, s_tau, s_XImats, s_topology_helpers, s_temp, aba_d_workspace, d_f_ext, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_qdd)[rep & 1023] = reinterpret_cast<const volatile T *>(s_qdd)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                d_qdd[ind] = s_qdd[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Compute the ABA (Articulated Body Algorithm)
     *
     * @param d_qdd is the vector of joint accelerations (output)
     * @param d_workspace is the L2-pinned global spill buffer (used at LITE/MINIMAL on h1_2-scale)
     * @param d_q_qd_tau is the vector of joint positions, velocities, torques
     * @param stride_q_qd is the stride between each q, qd
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void aba_kernel(T *d_qdd, unsigned char *d_workspace, const T *d_q_qd_tau, const int stride_q_qd, T *d_f_ext, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_qdd[7]
            //   T s_q_qd_tau[21]
            //   T s_va[84]
            //   T s_XImats[504]
            //   T s_temp[980]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_tau = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_va = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(84);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(980);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1596, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_tau; T *s_qd = &s_q_qd_tau[7]; T *s_tau = &s_q_qd_tau[14];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_tau_k = &d_q_qd_tau[k*stride_q_qd];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                    s_q_qd_tau[ind] = d_q_qd_tau_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                aba_inner<T, true, true>(s_qdd, s_va, s_q, s_qd, s_tau, s_XImats, s_topology_helpers, s_temp, nullptr, d_f_ext, gravity);
                __syncthreads();
                // save down to global
                T *d_qdd_k = &d_qdd[k*7];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    d_qdd_k[ind] = s_qdd[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_qdd[7]
            //   T s_q_qd_tau[21]
            //   T s_va[84]
            //   T s_XImats[504]
            //   T s_temp[980]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_tau = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_va = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(84);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(980);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1596, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_tau; T *s_qd = &s_q_qd_tau[7]; T *s_tau = &s_q_qd_tau[14];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_tau_k = &d_q_qd_tau[k*stride_q_qd];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                    s_q_qd_tau[ind] = d_q_qd_tau_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                aba_inner<T, true, true>(s_qdd, s_va, s_q, s_qd, s_tau, s_XImats, s_topology_helpers, s_temp, nullptr, d_f_ext, gravity);
                __syncthreads();
                // save down to global
                T *d_qdd_k = &d_qdd[k*7];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    d_qdd_k[ind] = s_qdd[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_qdd[7]
            //   T s_q_qd_tau[21]
            //   T s_va[84]
            //   T s_XImats[504]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_tau = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_va = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(84);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            T *s_temp = nullptr;
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(616, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_tau; T *s_qd = &s_q_qd_tau[7]; T *s_tau = &s_q_qd_tau[14];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_tau_k = &d_q_qd_tau[k*stride_q_qd];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                    s_q_qd_tau[ind] = d_q_qd_tau_k[ind];
                }
                __syncthreads();
                T *aba_d_workspace = reinterpret_cast<T *>(&d_workspace[k*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
                s_temp = aba_d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                aba_inner<T, false, true>(s_qdd, s_va, s_q, s_qd, s_tau, s_XImats, s_topology_helpers, s_temp, aba_d_workspace, d_f_ext, gravity);
                __syncthreads();
                // save down to global
                T *d_qdd_k = &d_qdd[k*7];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    d_qdd_k[ind] = s_qdd[ind];
                }
                __syncthreads();
            }
        }
    }

    /**
     * Compute the ABA (Articulated Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void aba(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "aba requires all-data or dynamics gridData");
        int stride_q_qd = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("aba", ABA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        aba_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,ABA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_qdd,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_qdd,hd_data->d_qdd,NUM_JOINTS*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the ABA (Articulated Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void aba_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "aba requires all-data or dynamics gridData");
        int stride_q_qd = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("aba", ABA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        aba_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,ABA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_qdd,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_qdd,hd_data->d_qdd,NUM_JOINTS*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call ABA %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the ABA (Articulated Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void aba_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "aba requires all-data or dynamics gridData");
        int stride_q_qd = 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("aba", ABA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        aba_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,ABA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_qdd,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,hd_data->d_f_ext,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
    }

    /**
     * Compute the Composite Rigid Body Algorithm
     *
     * Notes:
     *   Inner-controlled placement: TEMP_IN_SMEM selects where the scratch band lives (s_temp vs d_workspace). Decided at the top; caller sizes both arenas from CRBA_INNER_*_BYTES.
     *
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_M is a pointer to the matrix of inertias_XI is the pointer to the transformation and inertia matricies 
     * @param s_temp is the (shared) scratch; size CRBA_INNER_SMEM_BYTES<T, TEMP_IN_SMEM>() (the 140*NJ band when TEMP_IN_SMEM, else 0)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_workspace is the global scratch; size CRBA_INNER_WORKSPACE_BYTES<T, TEMP_IN_SMEM>() (the band when !TEMP_IN_SMEM, else 0). Pass nullptr when TEMP_IN_SMEM
     * @param gravity is the gravity constant
     */
    template <typename T, bool TEMP_IN_SMEM = true>
    __device__
    void crba_inner(T *s_M, const T *s_q, const T *s_qd, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, const T gravity) {
        if constexpr (!TEMP_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        unsigned char *s_linalg_smem = nullptr;
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 49; i += blockDim.x*blockDim.y){
            s_M[i] = static_cast<T>(0);
        }
        __syncthreads();
        T *alpha = &s_temp[0];
        T *s_fh = &s_temp[252];
        //
        // first loop (split into 2 parallel loops in bfs loop)
        // each bfs level runs in parallel
        //
        // pass updates where bfs_level is 6
        //     joints are: A7
        //     links are: L7
        grid_linalg_gemm<T,6,6,6,false,true>(&s_XImats[216], &s_XImats[468], &alpha[216], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&alpha[216], &s_XImats[216], &s_XImats[432], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // pass updates where bfs_level is 5
        //     joints are: A6
        //     links are: L6
        grid_linalg_gemm<T,6,6,6,false,true>(&s_XImats[180], &s_XImats[432], &alpha[180], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&alpha[180], &s_XImats[180], &s_XImats[396], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // pass updates where bfs_level is 4
        //     joints are: A5
        //     links are: L5
        grid_linalg_gemm<T,6,6,6,false,true>(&s_XImats[144], &s_XImats[396], &alpha[144], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&alpha[144], &s_XImats[144], &s_XImats[360], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // pass updates where bfs_level is 3
        //     joints are: A4
        //     links are: L4
        grid_linalg_gemm<T,6,6,6,false,true>(&s_XImats[108], &s_XImats[360], &alpha[108], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&alpha[108], &s_XImats[108], &s_XImats[324], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // pass updates where bfs_level is 2
        //     joints are: A3
        //     links are: L3
        grid_linalg_gemm<T,6,6,6,false,true>(&s_XImats[72], &s_XImats[324], &alpha[72], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&alpha[72], &s_XImats[72], &s_XImats[288], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // pass updates where bfs_level is 1
        //     joints are: A2
        //     links are: L2
        grid_linalg_gemm<T,6,6,6,false,true>(&s_XImats[36], &s_XImats[288], &alpha[36], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&alpha[36], &s_XImats[36], &s_XImats[252], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        //
        // Calculation of M[ind, ind] 
        //
        for(int jid = threadIdx.x + threadIdx.y*blockDim.x; jid < 7; jid += blockDim.x*blockDim.y){
            s_M[jid+jid*7] = s_XImats[252 + 36*jid + 6*2 + 2];
        }
        __syncthreads();
        //
        // Calculation of M[ind, parent]
        //
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 42; i += blockDim.x*blockDim.y){
            int jid = i / 6; int ind = i % 6;
            s_fh[i] = (1) * s_XImats[252 + 36*jid + 6*2 + ind];
        }
        __syncthreads();
        for(int jid = threadIdx.x + threadIdx.y*blockDim.x; jid < 7; jid += blockDim.x*blockDim.y){
            const int s_Sidx_by_jid[7] = {2, 2, 2, 2, 2, 2, 2};
            const T s_Ssgn_by_jid[7] = {1, 1, 1, 1, 1, 1, 1};
            int jid_parents[] = {-1, -1, -1, -1, -1, -1};
            int num_parents = 0;
            switch (jid) {
                case 0:
                    num_parents += 0;
                    break;
                case 1:
                    jid_parents[0] = 0;
                    num_parents += 1;
                    break;
                case 2:
                    jid_parents[0] = 1;
                    jid_parents[1] = 0;
                    num_parents += 2;
                    break;
                case 3:
                    jid_parents[0] = 2;
                    jid_parents[1] = 1;
                    jid_parents[2] = 0;
                    num_parents += 3;
                    break;
                case 4:
                    jid_parents[0] = 3;
                    jid_parents[1] = 2;
                    jid_parents[2] = 1;
                    jid_parents[3] = 0;
                    num_parents += 4;
                    break;
                case 5:
                    jid_parents[0] = 4;
                    jid_parents[1] = 3;
                    jid_parents[2] = 2;
                    jid_parents[3] = 1;
                    jid_parents[4] = 0;
                    num_parents += 5;
                    break;
                case 6:
                    jid_parents[0] = 5;
                    jid_parents[1] = 4;
                    jid_parents[2] = 3;
                    jid_parents[3] = 2;
                    jid_parents[4] = 1;
                    jid_parents[5] = 0;
                    num_parents += 6;
                    break;
            }
            T s_alpha[6];
            for (int i = 0; i < num_parents; i++) {
                int X_ind = i==0 ? jid : jid_parents[i-1];
                for (int k = 0; k < 6; k++) s_alpha[k] = s_fh[jid*6+k];
                for (int k = 0; k < 6; k++) s_fh[jid*6 + k] = dot_prod<T,6,1,1>(&s_XImats[36*X_ind+k*6], &s_alpha[0]);
                int parent_ind = jid_parents[i];
                s_M[jid*7 + parent_ind] = s_Ssgn_by_jid[parent_ind] * s_fh[jid*6 + s_Sidx_by_jid[parent_ind]];
                s_M[parent_ind*7 + jid] = s_M[jid*7 + parent_ind];
            }
        }
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param s_M is a pointer to the matrix of inertia
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant
     */
    template <typename T>
    __device__
    void crba_device(T *s_M, const T *s_q, const T *s_qd,const robotModel<T> *d_robotModel, const T gravity) {
        // GRID shared arena layout
        //   T s_XImats[504]
        //   T s_temp[798]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(798);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(1302, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        crba_inner<T, true>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param d_M is the pointer to the matrix of inertia
     * @param d_workspace is the L2-pinned global spill buffer (used at LITE/MINIMAL on large robots)
     * @param d_q_qd is the vector of joint positions and velocities
     * @param stride_q_qd is the stride between each q, qd
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void crba_kernel_single_timing(T *d_M, unsigned char *d_workspace, const T *d_q_qd, const int stride_q_qd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_M[49]
            //   T s_q_qd[14]
            //   T s_XImats[504]
            //   T s_temp[294]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_M = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(294);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(861, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 14; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd)[rep % (14)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_M into s_q_qd (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (14)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (14)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (14)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, true>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_M)[rep & 1023] = reinterpret_cast<const volatile T *>(s_M)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                d_M[ind] = s_M[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_M[49]
            //   T s_q_qd[14]
            //   T s_XImats[504]
            //   T s_temp[294]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_M = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(294);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(861, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 14; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd)[rep % (14)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_M into s_q_qd (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (14)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (14)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (14)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, true>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_M)[rep & 1023] = reinterpret_cast<const volatile T *>(s_M)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                d_M[ind] = s_M[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q_qd[14]
            //   T s_XImats[504]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            T *s_temp = nullptr;
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(518, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            T *s_M;  // repointed to the L2-pinned SO band (output spill) per timing branch
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd[ind];
            }
            __syncthreads();
            T *crba_d_workspace = reinterpret_cast<T *>(d_workspace);
            s_temp = crba_d_workspace;
            s_M = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 14; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd)[rep % (14)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_M into s_q_qd (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_M)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (14)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (14)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (14)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, false>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, crba_d_workspace, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_M)[rep & 1023] = reinterpret_cast<const volatile T *>(s_M)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                d_M[ind] = s_M[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param d_M is the pointer to the matrix of inertia
     * @param d_workspace is the L2-pinned global spill buffer (used at LITE/MINIMAL on large robots)
     * @param d_q_qd is the vector of joint positions and velocities
     * @param stride_q_qd is the stride between each q, qd
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void crba_kernel(T *d_M, unsigned char *d_workspace, const T *d_q_qd, const int stride_q_qd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_M[49]
            //   T s_q_qd[14]
            //   T s_XImats[504]
            //   T s_temp[294]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_M = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(294);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(861, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_k = &d_q_qd[k*stride_q_qd];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                    s_q_qd[ind] = d_q_qd_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, true>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
                __syncthreads();
                // save down to global
                T *d_M_k = &d_M[k*49];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                    d_M_k[ind] = s_M[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_M[49]
            //   T s_q_qd[14]
            //   T s_XImats[504]
            //   T s_temp[294]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_M = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(294);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(861, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_k = &d_q_qd[k*stride_q_qd];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                    s_q_qd[ind] = d_q_qd_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, true>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
                __syncthreads();
                // save down to global
                T *d_M_k = &d_M[k*49];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                    d_M_k[ind] = s_M[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q_qd[14]
            //   T s_XImats[504]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            T *s_temp = nullptr;
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(518, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            T *s_M;  // repointed to the L2-pinned SO band (output spill) per timing branch
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_k = &d_q_qd[k*stride_q_qd];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                    s_q_qd[ind] = d_q_qd_k[ind];
                }
                __syncthreads();
                T *crba_d_workspace = reinterpret_cast<T *>(&d_workspace[k*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
                s_temp = crba_d_workspace;
                s_M = reinterpret_cast<T *>(&d_workspace[k*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, false>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, crba_d_workspace, gravity);
                __syncthreads();
                // save down to global
                T *d_M_k = &d_M[k*49];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 49; ind += blockDim.x*blockDim.y){
                    d_M_k[ind] = s_M[ind];
                }
                __syncthreads();
            }
        }
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void crba(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "crba requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("crba", CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (USE_COMPRESSED_MEM) {crba_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {crba_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_M,hd_data->d_M,NUM_VEL*NUM_VEL*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void crba_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "crba requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("crba", CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        if (USE_COMPRESSED_MEM) {crba_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {crba_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_M,hd_data->d_M,NUM_VEL*NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call CRBA %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void crba_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "crba requires all-data or dynamics gridData");
        int stride_q_qd = USE_COMPRESSED_MEM ? 2*NUM_JOINTS : 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("crba", CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (USE_COMPRESSED_MEM) {crba_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {crba_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
    }

    /**
     * Finish the integrator step: write x_{k+1} from (q, qd, qdd) per the integrator type
     *
     * Notes:
     *   Assumes s_qdd is already computed for the current (s_q, s_qd, s_u)
     *   Floating-base: q-update uses an SE(3) Lie-group retract (grid_integrate_floating_q)
     *   Does not internally sync the thread group, so it should be called after all threads have finished computing their values
     *
     * @param s_x_kp1 is a pointer to memory for the next state (size NUM_POS + NUM_VEL)
     * @param s_q is the vector of joint positions (size NUM_POS)
     * @param s_qd is the vector of joint velocities (size NUM_VEL)
     * @param s_qdd is the vector of joint accelerations (size NUM_VEL, output of forward_dynamics)
     * @param dt is the integration timestep
     */
    template <typename T, IntegratorType IT>
    __device__
    void integrator_finish(T *s_x_kp1, const T *s_q, const T *s_qd, const T *s_qdd, const T dt) {
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
            s_x_kp1[7 + ind] = s_qd[ind] + dt * s_qdd[ind];
        }
        __syncthreads();
        if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_x_kp1[ind] = s_q[ind] + dt * s_qd[ind] + static_cast<T>(0.5) * dt * dt * s_qdd[ind];
            }
        }
        else {
            const T *s_src_v = (IT == IntegratorType::SEMI_IMPLICIT_EULER) ? &s_x_kp1[7] : s_qd;
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_x_kp1[ind] = s_q[ind] + dt * s_src_v[ind];
            }
        }
        static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL,
                      "integrator_finish only handles single-stage IT; multi-stage uses inner directly.");
    }

    /**
     * Computes a single integrator step (x_{k+1} = integrator(x_k, u_k, dt))
     *
     * Notes:
     *   Assumes s_XImats is updated already for the current s_q
     *   MINV_F_IN_SMEM selects where the FD inner's Minv 6*NV*NV F-region lives (s_temp vs d_workspace)
     *   For Midpoint/RK3/RK4, re-runs forward_dynamics at intermediate states and weights stage qdd outputs.
     *
     * @param s_x_kp1 is a pointer to memory for the next state (size NUM_POS + NUM_VEL)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_u is the vector of joint input torques
     * @param s_qdd is shared memory for the stage-1 joint accelerations (size NUM_VEL)
     * @param s_stage_qdd is shared memory for stages 2..N qdd outputs (size 21)
     * @param s_stage_point is shared memory for stages 2..N intermediate (q,qd) states (size 42)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_temp is the pointer to the shared memory needed of size: 716
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param d_workspace is the L2-pinned global scratch for the spilled Minv F-region (LITE/MINIMAL); nullptr at PERF
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, IntegratorType IT, bool MINV_F_IN_SMEM = true>
    __device__
    void integrator_inner(T *s_x_kp1, const T *s_q, const T *s_qd, const T *s_u, T *s_qdd, T *s_stage_qdd, T *s_stage_point, T *s_XImats, int *s_topology_helpers, const robotModel<T> *d_robotModel, T *s_temp, T *d_workspace, T *d_f_ext, const T gravity, const T dt) {
        forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
        __syncthreads();
        if constexpr (IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL) {
            integrator_finish<T, IT>(s_x_kp1, s_q, s_qd, s_qdd, dt);
        }
        else {
            T *s_qdd_2 = &s_stage_qdd[0];
            T *s_p1_q  = &s_stage_point[0];
            T *s_p1_qd = &s_stage_point[7];
            T *s_qdd_3 = &s_stage_qdd[7];
            T *s_p2_q  = &s_stage_point[14];
            T *s_p2_qd = &s_stage_point[21];
            T *s_qdd_4 = &s_stage_qdd[14];
            T *s_p3_q  = &s_stage_point[28];
            T *s_p3_qd = &s_stage_point[35];
            constexpr T c1 = static_cast<T>(0.5);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_p1_qd[ind] = s_qd[ind] + c1 * dt * s_qdd[ind];
            }
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_p1_q[ind]  = s_q[ind]  + c1 * dt * s_qd[ind];
            }
            __syncthreads();
            load_update_XImats_helpers<T>(s_XImats, s_p1_q, s_topology_helpers, d_robotModel, s_temp);
            __syncthreads();
            forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd_2, s_p1_q, s_p1_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
            __syncthreads();
            if constexpr (IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c2 = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : static_cast<T>(0.5);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_p2_qd[ind] = s_qd[ind] + c2 * dt * s_qdd_2[ind];
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_p2_q[ind]  = s_q[ind]  + c2 * dt * s_qd[ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_p2_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd_3, s_p2_q, s_p2_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
                __syncthreads();
            }
            if constexpr (IT == IntegratorType::RK4) {
                constexpr T c3 = static_cast<T>(1.0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_p3_qd[ind] = s_qd[ind] + c3 * dt * s_qdd_3[ind];
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_p3_q[ind]  = s_q[ind]  + c3 * dt * s_qd[ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_p3_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd_4, s_p3_q, s_p3_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
                __syncthreads();
            }
            // final assembly: v_{k+1} part — qd + dt * sum(b_i * qdd_i)
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                T accel = static_cast<T>(0);
                if constexpr (IT == IntegratorType::MIDPOINT) {
                    accel = s_qdd_2[ind];
                } else if constexpr (IT == IntegratorType::RK3) {
                    constexpr T b1 = static_cast<T>(2.0/9.0);
                    constexpr T b2 = static_cast<T>(3.0/9.0);
                    constexpr T b3 = static_cast<T>(4.0/9.0);
                    accel = b1 * s_qdd[ind] + b2 * s_qdd_2[ind] + b3 * s_qdd_3[ind];
                } else if constexpr (IT == IntegratorType::RK4) {
                    constexpr T b1 = static_cast<T>(1.0/6.0);
                    constexpr T b2 = static_cast<T>(2.0/6.0);
                    constexpr T b3 = static_cast<T>(2.0/6.0);
                    constexpr T b4 = static_cast<T>(1.0/6.0);
                    accel = b1 * s_qdd[ind] + b2 * s_qdd_2[ind] + b3 * s_qdd_3[ind] + b4 * s_qdd_4[ind];
                }
                s_x_kp1[7 + ind] = s_qd[ind] + dt * accel;
            }
            __syncthreads();
            // q_{k+1} part — Euler-style integrate(q, dt*qd) (TrajoptPlant convention)
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_x_kp1[ind] = s_q[ind] + dt * s_qd[ind];
            }
        }
    }

    /**
     * Computes a single integrator step using the precomputed robotModel
     *
     * @param s_x_kp1 is a pointer to memory for the next state (size NUM_POS + NUM_VEL)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_u is the vector of joint input torques
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER>
    __device__
    void integrator_device(T *s_x_kp1, const T *s_q, const T *s_qd, const T *s_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt) {
        // GRID shared arena layout
        //   T s_qdd[7]
        //   T s_stage_qdd[21]
        //   T s_stage_point[42]
        //   T s_XImats[504]
        //   T s_temp[716]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(7);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(21);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(42);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(504);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(716);
        int *s_topology_helpers = nullptr;
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(1290, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
    }

    /**
     * Computes a single integrator step per timestep (Euler by default)
     *
     * @param d_x_kp1 is a pointer to memory for the next state (size 2*NUM_VEL per timestep)
     * @param d_workspace is the L2-pinned global scratch for the spilled Minv F-region (LITE/MINIMAL tiers)
     * @param d_q_qd_u is the packed joint positions, velocities, and input torques
     * @param stride_q_qd_u is the stride between each (q, qd, u) tuple in d_q_qd_u
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(MAX_PERF_LEVEL_THREADS)
    void integrator_kernel_single_timing(T *d_x_kp1, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_qdd[7]
            //   T s_stage_qdd[21]
            //   T s_stage_point[42]
            //   T s_x_kp1[14]
            //   T s_XImats[504]
            //   T s_temp[716]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(716);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1325, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[7]; T *s_u = &s_q_qd_u[14];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 21; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (21)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_x_kp1 into s_q_qd_u (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (21)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (21)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_x_kp1)[rep & 1023] = reinterpret_cast<const volatile T *>(s_x_kp1)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                d_x_kp1[ind] = s_x_kp1[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_qdd[7]
            //   T s_stage_qdd[21]
            //   T s_stage_point[42]
            //   T s_x_kp1[14]
            //   T s_XImats[504]
            //   T s_temp[716]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(716);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1325, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[7]; T *s_u = &s_q_qd_u[14];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 21; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (21)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_x_kp1 into s_q_qd_u (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (21)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (21)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_x_kp1)[rep & 1023] = reinterpret_cast<const volatile T *>(s_x_kp1)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                d_x_kp1[ind] = s_x_kp1[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_qdd[7]
            //   T s_stage_qdd[21]
            //   T s_stage_point[42]
            //   T s_x_kp1[14]
            //   T s_XImats[504]
            //   T s_temp[422]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(422);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1031, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[7]; T *s_u = &s_q_qd_u[14];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            T *int_d_workspace = reinterpret_cast<T *>(&d_workspace[GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 21; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (21)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_x_kp1 into s_q_qd_u (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (21)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (21)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, false>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, int_d_workspace, d_f_ext, gravity, dt);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_x_kp1)[rep & 1023] = reinterpret_cast<const volatile T *>(s_x_kp1)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                d_x_kp1[ind] = s_x_kp1[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Computes a single integrator step per timestep (Euler by default)
     *
     * @param d_x_kp1 is a pointer to memory for the next state (size 2*NUM_VEL per timestep)
     * @param d_workspace is the L2-pinned global scratch for the spilled Minv F-region (LITE/MINIMAL tiers)
     * @param d_q_qd_u is the packed joint positions, velocities, and input torques
     * @param stride_q_qd_u is the stride between each (q, qd, u) tuple in d_q_qd_u
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(MAX_PERF_LEVEL_THREADS)
    void integrator_kernel(T *d_x_kp1, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_qdd[7]
            //   T s_stage_qdd[21]
            //   T s_stage_point[42]
            //   T s_x_kp1[14]
            //   T s_XImats[504]
            //   T s_temp[716]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(716);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1325, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[7]; T *s_u = &s_q_qd_u[14];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*14];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_qdd[7]
            //   T s_stage_qdd[21]
            //   T s_stage_point[42]
            //   T s_x_kp1[14]
            //   T s_XImats[504]
            //   T s_temp[716]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(716);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1325, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[7]; T *s_u = &s_q_qd_u[14];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*14];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_qdd[7]
            //   T s_stage_qdd[21]
            //   T s_stage_point[42]
            //   T s_x_kp1[14]
            //   T s_XImats[504]
            //   T s_temp[422]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(422);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1031, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[7]; T *s_u = &s_q_qd_u[14];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                T *int_d_workspace = reinterpret_cast<T *>(&d_workspace[k*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, false>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, int_d_workspace, d_f_ext, gravity, dt);
                __syncthreads();
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*14];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
    }

    /**
     * Run a single integrator step (default Euler) per timestep
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                      const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_u*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator", INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        integrator_kernel<T, IT, RESOURCE_TIER><<<block_dimms,thread_dimms,INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_x_kp1,hd_data->d_x_kp1,(NUM_POS + NUM_VEL)*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Run a single integrator step (default Euler) per timestep
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                                    const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_u*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator", INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()));}
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        integrator_kernel_single_timing<T, IT, RESOURCE_TIER><<<block_dimms,thread_dimms,INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_x_kp1,hd_data->d_x_kp1,(NUM_POS + NUM_VEL)*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call INTEGRATOR %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Run a single integrator step (default Euler) per timestep
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                                   const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator", INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        integrator_kernel<T, IT, RESOURCE_TIER><<<block_dimms,thread_dimms,INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
    }

    /**
     * integrator gradient orchestration as a single inner-owns-placement device function
     *
     * Notes:
     *   Owns the FD-grad inner s_temp pool placement; the repoint covers every consumer below (incl. the XImats helper's sincos scratch and the per-stage XImats refresh)
     *
     * @param s_dAB is the output [A | B] buffer (caller places); size 2*NUM_VEL*3*NUM_VEL = 294
     * @param s_q is the vector of joint positions (NON-const: mutated across RK stages)
     * @param s_qd is the vector of joint velocities (NON-const: mutated across RK stages)
     * @param s_u is the vector of joint input torques
     * @param s_df_du / s_dc_du / s_vaf / s_Minv / s_qdd are FD-grad in/out scratch (caller places)
     * @param s_q_orig / s_qd_orig / s_stage_grad_qdd / s_D_qdd_stage are multi-stage scratch (caller places; s_D_qdd_stage is a de-aliased workspace band when spilled)
     * @param s_dInt_q_6x6 / s_dInt_v_6x6 are the floating-base SE(3) dIntegrate blocks (unused fixed-base)
     * @param s_temp is the FD-grad inner scratch pool (used when SCRATCH_IN_SMEM)
     * @param d_workspace is the global scratch pool the FD-grad inner s_temp routes to (used when !SCRATCH_IN_SMEM)
     * @param d_temp_spill is the inverse_dynamics_gradient da_df band spill region (used when USE_DA_DF_SPILL)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant; dt is the timestep
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false>
    __device__ __forceinline__
    void integrator_gradient_device(T *s_dAB, T *s_q, T *s_qd, const T *s_u, T *s_df_du, T *s_dc_du, T *s_vaf, T *s_Minv, T *s_qdd, T *s_q_orig, T *s_qd_orig, T *s_stage_grad_qdd, T *s_D_qdd_stage, T *s_dInt_q_6x6, T *s_dInt_v_6x6, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt) {
        if constexpr(!SCRATCH_IN_SMEM){ s_temp = d_workspace; } else { (void)d_workspace; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        if constexpr (IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL) {
            //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
            minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
            inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
            forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
            __syncthreads();
            inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                int row = ind % 7; int dc_col_offset = ind - row;
                // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                T val = static_cast<T>(0);
                for(int col = 0; col < 7; col++) {
                    int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                    val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                }
                s_df_du[ind] = -val;
            }
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 294; ind += blockDim.x*blockDim.y){
                int row = ind % 14;
                int col = ind / 14;
                if constexpr (IT == IntegratorType::EULER) {
                    T val = static_cast<T>(0);
                    if (col < 7) {
                        // d/dq column
                        if (row < 7) {
                            val = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                        } else {
                            int i_local = row - 7;
                            val = dt * s_df_du[col * 7 + i_local];
                        }
                    } else if (col < 14) {
                        // d/dqd column
                        int j_local = col - 7;
                        if (row < 7) {
                            val = (row == j_local) ? dt : static_cast<T>(0);
                        } else {
                            int i_local = row - 7;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[49 + j_local * 7 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 14;
                        if (row < 7) {
                            val = static_cast<T>(0);
                        } else {
                            int i_local = row - 7;
                            int midx = (i_local <= j_local) * (j_local * 7 + i_local) + (i_local > j_local) * (i_local * 7 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::SEMI_IMPLICIT_EULER) {
                    T val = static_cast<T>(0);
                    T dt2 = dt * dt;
                    if (col < 7) {
                        // d/dq column
                        if (row < 7) {
                            T diag = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt2 * s_df_du[col * 7 + row];
                        } else {
                            int i_local = row - 7;
                            val = dt * s_df_du[col * 7 + i_local];
                        }
                    } else if (col < 14) {
                        // d/dqd column
                        int j_local = col - 7;
                        if (row < 7) {
                            T diag = (row == j_local) ? dt : static_cast<T>(0);
                            val = diag + dt2 * s_df_du[49 + j_local * 7 + row];
                        } else {
                            int i_local = row - 7;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[49 + j_local * 7 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 14;
                        if (row < 7) {
                            int midx = (row <= j_local) * (j_local * 7 + row) + (row > j_local) * (row * 7 + j_local);
                            val = dt2 * s_Minv[midx];
                        } else {
                            int i_local = row - 7;
                            int midx = (i_local <= j_local) * (j_local * 7 + i_local) + (i_local > j_local) * (i_local * 7 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
                    T val = static_cast<T>(0);
                    T dt2h = static_cast<T>(0.5) * dt * dt;
                    if (col < 7) {
                        // d/dq column
                        if (row < 7) {
                            T diag = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt2h * s_df_du[col * 7 + row];
                        } else {
                            int i_local = row - 7;
                            val = dt * s_df_du[col * 7 + i_local];
                        }
                    } else if (col < 14) {
                        // d/dqd column
                        int j_local = col - 7;
                        if (row < 7) {
                            T diag = (row == j_local) ? dt : static_cast<T>(0);
                            val = diag + dt2h * s_df_du[49 + j_local * 7 + row];
                        } else {
                            int i_local = row - 7;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[49 + j_local * 7 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 14;
                        if (row < 7) {
                            int midx = (row <= j_local) * (j_local * 7 + row) + (row > j_local) * (row * 7 + j_local);
                            val = dt2h * s_Minv[midx];
                        } else {
                            int i_local = row - 7;
                            int midx = (i_local <= j_local) * (j_local * 7 + i_local) + (i_local > j_local) * (i_local * 7 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else {
                    static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL,
                                  "dAB assembly handles single-stage IT only; Midpoint/RK3/RK4 are routed through gen_integrator_gradient_multistage.");
                }
            }
        }
        else {
            // --- multi-stage gradient: save original q, qd ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_q_orig[ind] = s_q[ind];
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_qd_orig[ind] = s_qd[ind];
            }
            __syncthreads();
            // --- multi-stage gradient: stage 1 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[0 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s1 = static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[0 * 147];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s1 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    s_D_qdd_cur[c * 7 + r] = base;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 2 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = s_q_orig[ind] + c_offset * dt * s_qd_orig[ind];
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[0 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[7 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s2 = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[1 * 147];
                T *s_D_qdd_prev = &s_D_qdd_stage[0];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s2 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 7; ++k) {
                        chain += s_df_du[49 + k * 7 + r] * s_D_qdd_prev[c * 7 + k];
                    }
                    s_D_qdd_cur[c * 7 + r] = base + c_prev_s2 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 3 ---
            if constexpr (IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = s_q_orig[ind] + c_offset * dt * s_qd_orig[ind];
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[7 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[14 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s3 = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[2 * 147];
                T *s_D_qdd_prev = &s_D_qdd_stage[147];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s3 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 7; ++k) {
                        chain += s_df_du[49 + k * 7 + r] * s_D_qdd_prev[c * 7 + k];
                    }
                    s_D_qdd_cur[c * 7 + r] = base + c_prev_s3 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 4 ---
            if constexpr (IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = s_q_orig[ind] + c_offset * dt * s_qd_orig[ind];
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[14 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[21 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s4 = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[3 * 147];
                T *s_D_qdd_prev = &s_D_qdd_stage[294];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s4 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 7; ++k) {
                        chain += s_df_du[49 + k * 7 + r] * s_D_qdd_prev[c * 7 + k];
                    }
                    s_D_qdd_cur[c * 7 + r] = base + c_prev_s4 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: assemble final dAB ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 294; ind += blockDim.x*blockDim.y){
                int row = ind % 14;
                int col = ind / 14;
                T val = static_cast<T>(0);
                if (row < 7) {
                    if (col < 7) {
                        val = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                    } else if (col < 14) {
                        val = (row == col - 7) ? dt : static_cast<T>(0);
                    } else {
                        val = static_cast<T>(0);
                    }
                } else {
                    int r = row - 7;
                    // bottom half: qd_{k+1} = qd + dt * sum(b_i * qdd_i)
                    T identity_term = ((col >= 7 && col < 14) && (r == col - 7)) ? static_cast<T>(1) : static_cast<T>(0);
                    T accel_term = static_cast<T>(0);
                    if constexpr (IT == IntegratorType::MIDPOINT) {
                        accel_term += static_cast<T>(1.0) * s_D_qdd_stage[147 + col * 7 + r];
                    }
                    if constexpr (IT == IntegratorType::RK3) {
                        accel_term += static_cast<T>(0.2222222222222222) * s_D_qdd_stage[0 + col * 7 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[147 + col * 7 + r];
                        accel_term += static_cast<T>(0.4444444444444444) * s_D_qdd_stage[294 + col * 7 + r];
                    }
                    if constexpr (IT == IntegratorType::RK4) {
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[0 + col * 7 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[147 + col * 7 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[294 + col * 7 + r];
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[441 + col * 7 + r];
                    }
                    val = identity_term + dt * accel_term;
                }
                s_dAB[ind] = val;
            }
            __syncthreads();
        }
    }

    /**
     * integrator gradient orchestration as a single inner-owns-placement device function
     *
     * Notes:
     *   Owns the FD-grad inner s_temp pool placement; the repoint covers every consumer below (incl. the XImats helper's sincos scratch and the per-stage XImats refresh)
     *
     * @param s_dAB is the output [A | B] buffer (caller places); size 2*NUM_VEL*3*NUM_VEL = 294
     * @param s_x_kp1 is the next-state output (caller places); size NUM_POS + NUM_VEL
     * @param s_q is the vector of joint positions (NON-const: mutated across RK stages)
     * @param s_qd is the vector of joint velocities (NON-const: mutated across RK stages)
     * @param s_u is the vector of joint input torques
     * @param s_df_du / s_dc_du / s_vaf / s_Minv / s_qdd are FD-grad in/out scratch (caller places)
     * @param s_q_orig / s_qd_orig / s_stage_grad_qdd / s_D_qdd_stage are multi-stage scratch (caller places; s_D_qdd_stage is a de-aliased workspace band when spilled)
     * @param s_dInt_q_6x6 / s_dInt_v_6x6 are the floating-base SE(3) dIntegrate blocks (unused fixed-base)
     * @param s_temp is the FD-grad inner scratch pool (used when SCRATCH_IN_SMEM)
     * @param d_workspace is the global scratch pool the FD-grad inner s_temp routes to (used when !SCRATCH_IN_SMEM)
     * @param d_temp_spill is the inverse_dynamics_gradient da_df band spill region (used when USE_DA_DF_SPILL)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant; dt is the timestep
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false>
    __device__ __forceinline__
    void integrator_with_gradient_device(T *s_dAB, T *s_x_kp1, T *s_q, T *s_qd, const T *s_u, T *s_df_du, T *s_dc_du, T *s_vaf, T *s_Minv, T *s_qdd, T *s_q_orig, T *s_qd_orig, T *s_stage_grad_qdd, T *s_D_qdd_stage, T *s_dInt_q_6x6, T *s_dInt_v_6x6, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt) {
        if constexpr(!SCRATCH_IN_SMEM){ s_temp = d_workspace; } else { (void)d_workspace; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        if constexpr (IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL) {
            //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
            minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
            inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
            forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
            __syncthreads();
            inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                int row = ind % 7; int dc_col_offset = ind - row;
                // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                T val = static_cast<T>(0);
                for(int col = 0; col < 7; col++) {
                    int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                    val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                }
                s_df_du[ind] = -val;
            }
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 294; ind += blockDim.x*blockDim.y){
                int row = ind % 14;
                int col = ind / 14;
                if constexpr (IT == IntegratorType::EULER) {
                    T val = static_cast<T>(0);
                    if (col < 7) {
                        // d/dq column
                        if (row < 7) {
                            val = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                        } else {
                            int i_local = row - 7;
                            val = dt * s_df_du[col * 7 + i_local];
                        }
                    } else if (col < 14) {
                        // d/dqd column
                        int j_local = col - 7;
                        if (row < 7) {
                            val = (row == j_local) ? dt : static_cast<T>(0);
                        } else {
                            int i_local = row - 7;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[49 + j_local * 7 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 14;
                        if (row < 7) {
                            val = static_cast<T>(0);
                        } else {
                            int i_local = row - 7;
                            int midx = (i_local <= j_local) * (j_local * 7 + i_local) + (i_local > j_local) * (i_local * 7 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::SEMI_IMPLICIT_EULER) {
                    T val = static_cast<T>(0);
                    T dt2 = dt * dt;
                    if (col < 7) {
                        // d/dq column
                        if (row < 7) {
                            T diag = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt2 * s_df_du[col * 7 + row];
                        } else {
                            int i_local = row - 7;
                            val = dt * s_df_du[col * 7 + i_local];
                        }
                    } else if (col < 14) {
                        // d/dqd column
                        int j_local = col - 7;
                        if (row < 7) {
                            T diag = (row == j_local) ? dt : static_cast<T>(0);
                            val = diag + dt2 * s_df_du[49 + j_local * 7 + row];
                        } else {
                            int i_local = row - 7;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[49 + j_local * 7 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 14;
                        if (row < 7) {
                            int midx = (row <= j_local) * (j_local * 7 + row) + (row > j_local) * (row * 7 + j_local);
                            val = dt2 * s_Minv[midx];
                        } else {
                            int i_local = row - 7;
                            int midx = (i_local <= j_local) * (j_local * 7 + i_local) + (i_local > j_local) * (i_local * 7 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
                    T val = static_cast<T>(0);
                    T dt2h = static_cast<T>(0.5) * dt * dt;
                    if (col < 7) {
                        // d/dq column
                        if (row < 7) {
                            T diag = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt2h * s_df_du[col * 7 + row];
                        } else {
                            int i_local = row - 7;
                            val = dt * s_df_du[col * 7 + i_local];
                        }
                    } else if (col < 14) {
                        // d/dqd column
                        int j_local = col - 7;
                        if (row < 7) {
                            T diag = (row == j_local) ? dt : static_cast<T>(0);
                            val = diag + dt2h * s_df_du[49 + j_local * 7 + row];
                        } else {
                            int i_local = row - 7;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[49 + j_local * 7 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 14;
                        if (row < 7) {
                            int midx = (row <= j_local) * (j_local * 7 + row) + (row > j_local) * (row * 7 + j_local);
                            val = dt2h * s_Minv[midx];
                        } else {
                            int i_local = row - 7;
                            int midx = (i_local <= j_local) * (j_local * 7 + i_local) + (i_local > j_local) * (i_local * 7 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else {
                    static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL,
                                  "dAB assembly handles single-stage IT only; Midpoint/RK3/RK4 are routed through gen_integrator_gradient_multistage.");
                }
            }
            __syncthreads();
            integrator_finish<T, IT>(s_x_kp1, s_q, s_qd, s_qdd, dt);
        }
        else {
            // --- multi-stage gradient: save original q, qd ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_q_orig[ind] = s_q[ind];
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_qd_orig[ind] = s_qd[ind];
            }
            __syncthreads();
            // --- multi-stage gradient: stage 1 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[0 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s1 = static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[0 * 147];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s1 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    s_D_qdd_cur[c * 7 + r] = base;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 2 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = s_q_orig[ind] + c_offset * dt * s_qd_orig[ind];
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[0 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[7 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s2 = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[1 * 147];
                T *s_D_qdd_prev = &s_D_qdd_stage[0];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s2 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 7; ++k) {
                        chain += s_df_du[49 + k * 7 + r] * s_D_qdd_prev[c * 7 + k];
                    }
                    s_D_qdd_cur[c * 7 + r] = base + c_prev_s2 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 3 ---
            if constexpr (IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = s_q_orig[ind] + c_offset * dt * s_qd_orig[ind];
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[7 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[14 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s3 = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[2 * 147];
                T *s_D_qdd_prev = &s_D_qdd_stage[147];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s3 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 7; ++k) {
                        chain += s_df_du[49 + k * 7 + r] * s_D_qdd_prev[c * 7 + k];
                    }
                    s_D_qdd_cur[c * 7 + r] = base + c_prev_s3 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 4 ---
            if constexpr (IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_q[ind] = s_q_orig[ind] + c_offset * dt * s_qd_orig[ind];
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[14 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[7], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 98; ind += blockDim.x*blockDim.y){
                    int row = ind % 7; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 7; col++) {
                        int index = (row <= col) * (col * 7 + row) + (row > col) * (row * 7 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[21 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s4 = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[3 * 147];
                T *s_D_qdd_prev = &s_D_qdd_stage[294];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 147; ind += blockDim.x*blockDim.y){
                    int r = ind % 7;
                    int c = ind / 7;
                    T base = static_cast<T>(0);
                    if (c < 7) {
                        base = s_df_du[c * 7 + r];                       // J_qq[r, c]
                    } else if (c < 14) {
                        int cc = c - 7;
                        base = c_prev_s4 * dt * s_df_du[cc * 7 + r] + s_df_du[49 + cc * 7 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 14;
                        int midx = (r <= cc) * (cc * 7 + r) + (r > cc) * (r * 7 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 7; ++k) {
                        chain += s_df_du[49 + k * 7 + r] * s_D_qdd_prev[c * 7 + k];
                    }
                    s_D_qdd_cur[c * 7 + r] = base + c_prev_s4 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: assemble final dAB ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 294; ind += blockDim.x*blockDim.y){
                int row = ind % 14;
                int col = ind / 14;
                T val = static_cast<T>(0);
                if (row < 7) {
                    if (col < 7) {
                        val = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                    } else if (col < 14) {
                        val = (row == col - 7) ? dt : static_cast<T>(0);
                    } else {
                        val = static_cast<T>(0);
                    }
                } else {
                    int r = row - 7;
                    // bottom half: qd_{k+1} = qd + dt * sum(b_i * qdd_i)
                    T identity_term = ((col >= 7 && col < 14) && (r == col - 7)) ? static_cast<T>(1) : static_cast<T>(0);
                    T accel_term = static_cast<T>(0);
                    if constexpr (IT == IntegratorType::MIDPOINT) {
                        accel_term += static_cast<T>(1.0) * s_D_qdd_stage[147 + col * 7 + r];
                    }
                    if constexpr (IT == IntegratorType::RK3) {
                        accel_term += static_cast<T>(0.2222222222222222) * s_D_qdd_stage[0 + col * 7 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[147 + col * 7 + r];
                        accel_term += static_cast<T>(0.4444444444444444) * s_D_qdd_stage[294 + col * 7 + r];
                    }
                    if constexpr (IT == IntegratorType::RK4) {
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[0 + col * 7 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[147 + col * 7 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[294 + col * 7 + r];
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[441 + col * 7 + r];
                    }
                    val = identity_term + dt * accel_term;
                }
                s_dAB[ind] = val;
            }
            __syncthreads();
            // --- multi-stage gradient: assemble x_{k+1} ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                T accel = static_cast<T>(0);
                if constexpr (IT == IntegratorType::MIDPOINT) {
                    accel += static_cast<T>(1.0) * s_stage_grad_qdd[7 + ind];
                }
                if constexpr (IT == IntegratorType::RK3) {
                    accel += static_cast<T>(0.2222222222222222) * s_stage_grad_qdd[0 + ind];
                    accel += static_cast<T>(0.3333333333333333) * s_stage_grad_qdd[7 + ind];
                    accel += static_cast<T>(0.4444444444444444) * s_stage_grad_qdd[14 + ind];
                }
                if constexpr (IT == IntegratorType::RK4) {
                    accel += static_cast<T>(0.16666666666666666) * s_stage_grad_qdd[0 + ind];
                    accel += static_cast<T>(0.3333333333333333) * s_stage_grad_qdd[7 + ind];
                    accel += static_cast<T>(0.3333333333333333) * s_stage_grad_qdd[14 + ind];
                    accel += static_cast<T>(0.16666666666666666) * s_stage_grad_qdd[21 + ind];
                }
                s_x_kp1[7 + ind] = s_qd_orig[ind] + dt * accel;
            }
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                s_x_kp1[ind] = s_q_orig[ind] + dt * s_qd_orig[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Computes the gradient of the integrator step per timestep
     *
     * @param d_dAB is a pointer to memory for [A | B] of size 2*NUM_VEL*3*NUM_VEL per timestep
     * @param d_workspace is the L2-pinned global scratch for the spilled s_D_qdd_stage (LITE/MINIMAL tiers)
     * @param d_q_qd_u is the packed joint positions, velocities, and input torques
     * @param stride_q_qd_u is the stride between each (q, qd, u) tuple in d_q_qd_u
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(MAX_PERF_LEVEL_THREADS)
    void integrator_gradient_kernel_single_timing(T *d_dAB, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_dAB[294]
            //   T s_df_du[98]
            //   T s_dc_du[98]
            //   T s_vaf[126]
            //   T s_Minv[49]
            //   T s_qdd[7]
            //   T s_q_orig[7]
            //   T s_qd_orig[7]
            //   T s_stage_grad_qdd[28]
            //   T s_D_qdd_stage[588]
            //   T s_dInt_q_6x6[36]
            //   T s_dInt_v_6x6[36]
            //   T s_XImats[504]
            //   T s_temp[1722]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dAB = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(294);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(98);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dc_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(98);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(126);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_grad_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(28);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_D_qdd_stage = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(588);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_q_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_v_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1722);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(3621, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[7]; T *s_u = &s_q_qd_u[14];
            T *d_temp_spill = nullptr; (void)d_temp_spill;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 21; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 21; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (21)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_dAB into s_q_qd_u (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_dAB)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_dAB)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_dAB)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (21)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (21)] += _aopt_fb3;
                }
                __syncthreads();
                integrator_gradient_device<T, IT, true, false>(s_dAB, s_q, s_qd, s_u, s_df_du, s_dc_du, s_vaf, s_Minv, s_qdd, s_q_orig, s_qd_orig, s_stage_grad_qdd, s_D_qdd_stage, s_dInt_q_6x6, s_dInt_v_6x6, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, d_robotModel, d_f_ext, gravity, dt);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_dAB)[rep & 1023] = reinterpret_cast<const volatile T *>(s_dAB)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 294; ind += blockDim.x*blockDim.y){
                d_dAB[ind] = s_dAB[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q_qd_u[21]
            //   T s_dAB[294]
            //   T s_df_du[98]
            //   T s_dc_du[98]
            //   T s_vaf[126]
            //   T s_Minv[49]
            //   T s_qdd[7]
            //   T s_q_orig[7]
            //   T s_qd_orig[7]
            //   T s_stage_grad_qdd[28]
            //   T s_D_qdd_stage[588]
            //   T s_dInt_q_6x6[36]
            //   T s_dInt_v_6x6[36]
            //   T s_XImats[504]
            //   T s_temp[1722]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(21);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dAB = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(294);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(98);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dc_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(98);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(126);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(49);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
