                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (21)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (21)] += _aopt_fb3;
                }
