            //   T s_vaf[126]
            //   T s_Minv[49]
            //   T s_qdd[7]
            //   T s_q_orig[7]
            //   T s_qd_orig[7]
            //   T s_stage_grad_qdd[28]
            //   T s_dInt_q_6x6[36]
