         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant,
         * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
         * @param streams are pointers to CUDA streams for async memory transfers (if needed)
         */
        template <typename T, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
        __host__
        void fdsva_so(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                              const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "fdsva_so requires all-data or dynamics gridData");
            int stride_q_qd_qdd = Q_QD_U_STRIDE;
            // start code with memory transfer
            gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_qdd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
            gpuErrchkKernel();
            // call the kernel
            gpuErrchk(grid_check_dynamic_shared_memory_bytes("fdsva_so", FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
            if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*GRID_WORKSPACE_SLOTS*num_timesteps));}
            fdsva_so_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_df2,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,hd_data->d_idsva_so,d_robotModel,gravity,num_timesteps);
            gpuErrchkKernel();
            if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_end_l2_persisting(0));}
            // finally transfer the result back
            gpuErrchk(cudaMemcpy(hd_data->h_df2,hd_data->d_df2,num_timesteps*1372*sizeof(T),cudaMemcpyDeviceToHost));
            gpuErrchkKernel();
        }

        /**
         * Compute the FDSVA_SO (Second Order of Forward Dynamics with Spacial Vector Algebra)
         *
         * @param hd_data is the packaged input and output pointers
         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant,
         * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
         * @param streams are pointers to CUDA streams for async memory transfers (if needed)
         */
        template <typename T, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
        __host__
        void fdsva_so_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                            const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "fdsva_so requires all-data or dynamics gridData");
            int stride_q_qd_qdd = Q_QD_U_STRIDE;
            // start code with memory transfer
            gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_qdd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
            gpuErrchkKernel();
            // call the kernel
            gpuErrchk(grid_check_dynamic_shared_memory_bytes("fdsva_so", FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
            if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*GRID_WORKSPACE_SLOTS*1));}
            struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
            fdsva_so_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_df2,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,hd_data->d_idsva_so,d_robotModel,gravity,num_timesteps);
            gpuErrchkKernel();
            clock_gettime(CLOCK_MONOTONIC,&end);
            if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_end_l2_persisting(0));}
            // finally transfer the result back
            gpuErrchk(cudaMemcpy(hd_data->h_df2,hd_data->d_df2,1372*sizeof(T),cudaMemcpyDeviceToHost));
            gpuErrchkKernel();
            printf("Single Call FDSVA_SO %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
        }

        /**
         * Compute the FDSVA_SO (Second Order of Forward Dynamics with Spacial Vector Algebra)
         *
         * @param hd_data is the packaged input and output pointers
         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant,
         * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
         * @param streams are pointers to CUDA streams for async memory transfers (if needed)
         */
        template <typename T, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
        __host__
        void fdsva_so_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                           const dim3 block_dimms, const dim3 thread_dimms) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "fdsva_so requires all-data or dynamics gridData");
            int stride_q_qd_qdd = Q_QD_U_STRIDE;
            // call the kernel
            gpuErrchk(grid_check_dynamic_shared_memory_bytes("fdsva_so", FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
            if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*GRID_WORKSPACE_SLOTS*num_timesteps));}
            fdsva_so_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_df2,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,hd_data->d_idsva_so,d_robotModel,gravity,num_timesteps);
            gpuErrchkKernel();
            if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_end_l2_persisting(0));}
        }

        /**
         * integrator hessian (plant_step_hessian s_d2AB surface): composes fdsva_so + dt-scaled assembly
         *
         * @param s_d2AB is the output Hessian (2*NUM_VEL x 3*NUM_VEL x 3*NUM_VEL, row-major); size 6174
         * @param s_df2/s_idsva_so/s_Minv/s_df_du/s_qdd are fdsva_so in/out scratch (caller places)
         * @param s_q/s_qd/s_u are the joint positions, velocities, and input torques
         * @param s_temp is the fdsva_so shared scratch pool (used when SCRATCH_IN_SMEM)
         * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
         * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
         * @param d_workspace/d_fd_grad_spill/s_fdsva_temp are fdsva_so spill regions (SHARED tier: nullptr)
         * @param d_robotModel holds XImats/topology; gravity is the gravity constant; dt is the timestep
         */
        template <typename T, IntegratorType IT = IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool FD_GRAD_USE_SPILL = false, bool CONTRACT_IN_SMEM = true>
        __device__ __forceinline__
        void integrator_hessian_device(T *s_d2AB, T *s_df2, T *s_idsva_so, T *s_Minv, T *s_df_du, T *s_qdd, const T *s_q, const T *s_qd, const T *s_u, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_fd_grad_spill, T *s_fdsva_temp, const robotModel<T> *d_robotModel, const T gravity, const T dt) {
            static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER,
                "integrator_hessian_device: only EULER / SEMI_IMPLICIT_EULER are supported "
                "(multi-stage RK 2nd-order chain rule is deferred; see f1_plant_step_hessian_plan.md).");
            fdsva_so_device<T, SCRATCH_IN_SMEM, FD_GRAD_USE_SPILL, CONTRACT_IN_SMEM>(s_df2, s_idsva_so, s_Minv, s_df_du, s_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_fd_grad_spill, s_fdsva_temp, d_robotModel, gravity);
            __syncthreads();
            T *d2a_dqdq = s_df2;
            T *d2a_dvdq = &s_df2[343];
            T *d2a_dvdv = &s_df2[686];
            T *d2a_dtdq = &s_df2[1029];
            const bool si = (IT == IntegratorType::SEMI_IMPLICIT_EULER);
            const T dt2 = dt * dt;
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6174; ind += blockDim.x*blockDim.y){
                int o = ind / 441;
                int a = (ind / 21) % 21;
                int b = ind % 21;
                int i = o % 7;  // qdd component index for this output row
                T d2 = static_cast<T>(0);
                int ablk = a / 7; int bblk = b / 7;
                int aj = a % 7; int bk = b % 7;
                if (ablk == 0 && bblk == 0)      d2 = d2a_dqdq[i*49 + aj*7 + bk];  // [q,q]
                else if (ablk == 1 && bblk == 1) d2 = d2a_dvdv[i*49 + aj*7 + bk];  // [qd,qd]
                else if (ablk == 1 && bblk == 0) d2 = d2a_dvdq[i*49 + aj*7 + bk];  // [qd,q]
                else if (ablk == 0 && bblk == 1) d2 = d2a_dvdq[i*49 + bk*7 + aj];  // [q,qd] = [qd,q]^T(jk)
                else if (ablk == 2 && bblk == 0) d2 = d2a_dtdq[i*49 + aj*7 + bk];  // [u,q]
                else if (ablk == 0 && bblk == 2) d2 = d2a_dtdq[i*49 + bk*7 + aj];  // [q,u] = [u,q]^T(jk)
                // all u-u / u-qd / qd-u blocks are identically zero (qdd linear in u).
                T scale = (o < 7) ? (si ? dt2 : static_cast<T>(0)) : dt;
                s_d2AB[ind] = scale * d2;
            }
            __syncthreads();
        }

        /**
         * Compute the generalized gravity g(q) = RNEA(q, 0, 0)
         *
         * @param s_out is the output bias torque (size NUM_VEL)
         * @param s_q is the vector of joint positions
         * @param s_qd is the vector of joint velocities (ignored for gravity)
         * @param d_robotModel is the GPU model helpers
         * @param gravity is the gravity constant
         */
        template <typename T>
        __device__
        void generalized_gravity_device(T *s_out, const T *s_q, const T *s_qd, const robotModel<T> *d_robotModel, const T gravity) {
            // GRID shared arena layout
            //   T s_vaf[126]
            //   T s_qd0[7]
            //   T s_XImats[504]
            //   T s_temp[42]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(126);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd0 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(679, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 7; i += blockDim.x*blockDim.y){
                s_qd0[i] = static_cast<T>(0);
            }
            __syncthreads();
            inverse_dynamics_inner<T>(s_out, s_vaf, s_q, s_qd0, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
        }

        /**
         * Compute generalized_gravity (RNEA bias) per timestep
         *
         */
        template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
        __global__
        __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
        void generalized_gravity_kernel_single_timing(T *d_out, unsigned char *d_workspace, const T *d_q_qd, const int stride_q_qd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
            (void)d_workspace;
            // GRID shared arena layout
            //   T s_q_qd[14]
            //   T s_out[7]
            //   T s_vaf[126]
            //   T s_qd0[7]
            //   T s_XImats[504]
            //   T s_temp[42]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_out = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(126);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd0 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(700, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            (void)s_qd;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd[ind];
            }
            __syncthreads();
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 14; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd)[rep % (14)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_out into s_q_qd (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_out)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_out)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_out)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (14)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (14)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (14)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 7; i += blockDim.x*blockDim.y){
                    s_qd0[i] = static_cast<T>(0);
                }
                __syncthreads();
                inverse_dynamics_inner<T>(s_out, s_vaf, s_q, s_qd0, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_out)[rep & 1023] = reinterpret_cast<const volatile T *>(s_out)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                d_out[ind] = s_out[ind];
            }
            __syncthreads();
        }

        /**
         * Compute generalized_gravity (RNEA bias) per timestep
         *
         */
        template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
        __global__
        __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
        void generalized_gravity_kernel(T *d_out, unsigned char *d_workspace, const T *d_q_qd, const int stride_q_qd, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
            (void)d_workspace;
            // GRID shared arena layout
            //   T s_q_qd[14]
            //   T s_out[7]
            //   T s_vaf[126]
            //   T s_qd0[7]
            //   T s_XImats[504]
            //   T s_temp[42]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(14);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_out = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(126);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd0 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(504);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(42);
            int *s_topology_helpers = nullptr;
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(700, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[7];
            (void)s_qd;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_k = &d_q_qd[k*stride_q_qd];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                    s_q_qd[ind] = d_q_qd_k[ind];
                }
                __syncthreads();
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 7; i += blockDim.x*blockDim.y){
                    s_qd0[i] = static_cast<T>(0);
                }
                __syncthreads();
                inverse_dynamics_inner<T>(s_out, s_vaf, s_q, s_qd0, s_XImats, s_topology_helpers, s_temp, nullptr, gravity);
                __syncthreads();
                // save down to global
                T *d_out_k = &d_out[k*7];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                    d_out_k[ind] = s_out[ind];
                }
                __syncthreads();
            }
        }

        /**
         * Compute generalized_gravity (RNEA bias)
         *
         */
        template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL>
        __host__
        void generalized_gravity(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                              const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "generalized_gravity requires all-data or dynamics gridData");
            // start code with memory transfer
            int stride_q_qd;
            if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
            else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
            // then call the kernel
            gpuErrchk(grid_check_dynamic_shared_memory_bytes("generalized_gravity", INVERSE_DYNAMICS_BIAS_DYNAMIC_SHARED_MEM_BYTES<T>()));
            if (USE_COMPRESSED_MEM) {generalized_gravity_kernel<T><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_BIAS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
            else                    {generalized_gravity_kernel<T><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_BIAS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
            gpuErrchkKernel();
            // finally transfer the result back
            gpuErrchk(cudaMemcpy(hd_data->h_c,hd_data->d_c,NUM_VEL*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
            gpuErrchkKernel();
        }

        /**
         * Compute generalized_gravity (RNEA bias)
         *
         */
        template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL>
        __host__
        void generalized_gravity_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                            const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "generalized_gravity requires all-data or dynamics gridData");
            // start code with memory transfer
            int stride_q_qd;
            if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
            else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
            // then call the kernel
            gpuErrchk(grid_check_dynamic_shared_memory_bytes("generalized_gravity", INVERSE_DYNAMICS_BIAS_DYNAMIC_SHARED_MEM_BYTES<T>()));
            struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
            if (USE_COMPRESSED_MEM) {generalized_gravity_kernel_single_timing<T><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_BIAS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
            else                    {generalized_gravity_kernel_single_timing<T><<<block_dimms,thread_dimms,INVERSE_DYNAMICS_BIAS_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_c,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
            gpuErrchkKernel();
            clock_gettime(CLOCK_MONOTONIC,&end);
            // finally transfer the result back
            gpuErrchk(cudaMemcpy(hd_data->h_c,hd_data->d_c,NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
            gpuErrchkKernel();
            printf("Single Call GENERALIZED_GRAVITY %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
        }

        /**
         * Compute generalized_gravity (RNEA bias)
         *
         */
        template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL>
        __host__
        void generalized_gravity_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                           const dim3 block_dimms, const dim3 thread_dimms) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "generalized_gravity requires all-data or dynamics gridData");
            int stride_q_qd = USE_COMPRESSED_MEM ? 2*NUM_JOINTS : 3*NUM_JOINTS;
