                    }
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                        s_u[ind] = d_u[k*stride_u + ind];
                    }
                    __syncthreads();
                    T *d_ws = reinterpret_cast<T *>(&d_workspace[k*PLANT_HESSIAN_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
                    size_t ws_off = 0;
                    T *s_d2AB = &d_ws[ws_off]; ws_off += 6174;
                    T *s_df2 = &d_ws[ws_off]; ws_off += 1372;
                    T *s_idsva_so = &d_ws[ws_off]; ws_off += 1372;
                    T *s_fdsva_pool = &d_ws[ws_off]; ws_off += 3744;
                    (void)ws_off;
                    plant_step_hessian<T, IT, false, false, false>(s_d2AB, s_x, s_u, s_df2, s_idsva_so, s_Minv, s_df_du, s_qdd, s_XImats, s_topology_helpers, s_temp, s_fdsva_pool, nullptr, s_fdsva_pool, d_robotModel, gravity, dt);
                    __syncthreads();
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6174; ind += blockDim.x*blockDim.y){
                        d_d2AB[k*6174 + ind] = s_d2AB[ind];
                    }
                    __syncthreads();
                }
            }
            else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
                // GRID shared arena layout
                //   T s_x[14]
                //   T s_u[7]
                //   T s_Minv[49]
                //   T s_df_du[98]
                //   T s_qdd[7]
                //   T s_XImats[504]
                //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
                extern __shared__ __align__(16) unsigned char s_arena[];
                size_t s_arena_offset = 0;
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_x = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(14);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(7);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(49);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(98);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(7);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(504);
                T *s_temp = nullptr;
                int *s_topology_helpers = nullptr;
                unsigned char *s_linalg_smem = nullptr;
                if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                    s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                    s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                    s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
                }
                #ifdef GRID_CUDA_DEBUG_LAYOUT
                assert(s_arena_offset == grid_shared_arena_bytes<T>(679, 0, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
                #endif
                (void)s_arena_offset;
                for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 14; ind += blockDim.x*blockDim.y){
                        s_x[ind] = d_x[k*stride_x + ind];
                    }
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7; ind += blockDim.x*blockDim.y){
                        s_u[ind] = d_u[k*stride_u + ind];
                    }
                    __syncthreads();
                    T *d_ws = reinterpret_cast<T *>(&d_workspace[k*PLANT_HESSIAN_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
                    size_t ws_off = 0;
                    T *s_d2AB = &d_ws[ws_off]; ws_off += 6174;
                    T *s_df2 = &d_ws[ws_off]; ws_off += 1372;
                    T *s_idsva_so = &d_ws[ws_off]; ws_off += 1372;
                    T *s_fdsva_pool = &d_ws[ws_off]; ws_off += 3744;
                    (void)ws_off;
                    plant_step_hessian<T, IT, false, false, false>(s_d2AB, s_x, s_u, s_df2, s_idsva_so, s_Minv, s_df_du, s_qdd, s_XImats, s_topology_helpers, s_temp, s_fdsva_pool, nullptr, s_fdsva_pool, d_robotModel, gravity, dt);
                    __syncthreads();
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6174; ind += blockDim.x*blockDim.y){
                        d_d2AB[k*6174 + ind] = s_d2AB[ind];
                    }
                    __syncthreads();
                }
            }
        }

        template <typename T, int TIER = grid::GRID_DEFAULT_RESOURCE_TIER> __host__ __device__ inline size_t INTEGRATOR_HESSIAN_DYNAMIC_SHARED_MEM_BYTES() { if constexpr (TIER == grid::TIER_SHARED)    return grid::grid_shared_arena_bytes<T>(13341, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); else if constexpr (TIER == grid::TIER_LITE) return grid::grid_shared_arena_bytes<T>(679, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); else                                        return grid::grid_shared_arena_bytes<T>(679, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); }
        static const int GRID_PLANT_HESSIAN_USES_WORKSPACE_ANY_TIER = 1;
        #define GRID_PLANT_HAS_STEP_HESSIAN 1
        /**
         * ee_pos_cost_kernel: value + grad_x + GN hess_x per timestep (EE=0)
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad grad over x (14 per timestep)
         * @param d_hess dense col-major x-hessian (196 per timestep)
         * @param d_q joint positions (NUM_POS per timestep)
         * @param d_p_des desired EE position (3 per timestep)
         * @param d_W per-axis weight (3 per timestep)
         * @param d_end_effector_pose / d_end_effector_pose_gradient global scratch (6*NUM_EES / 6*NUM_VEL*NUM_EES per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, int EE = 0, bool MUJOCO_OUTPUT = false>
        __global__
        void ee_pos_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_p_des, const T *d_W, T *d_end_effector_pose, T *d_end_effector_pose_gradient, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
            extern __shared__ __align__(16) T s_ee_arena[];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                const T *s_q = &d_q[k*7]; const T *s_p_des = &d_p_des[k*3]; const T *s_W = &d_W[k*3];
                T *s_end_effector_pose = &d_end_effector_pose[k*6]; T *s_end_effector_pose_gradient = &d_end_effector_pose_gradient[k*42];
                ee_pos_cost<T, EE>(&d_out[k], s_q, s_p_des, s_W, s_end_effector_pose, s_ee_arena, d_robotModel);
                __syncthreads();
                ee_pos_cost_gradient<T, EE>(&d_grad[k*14], s_q, s_p_des, s_W, s_end_effector_pose, s_end_effector_pose_gradient, s_ee_arena, d_robotModel);
                __syncthreads();
                ee_pos_cost_hessian<T, EE>(&d_hess[k*196], s_q, s_W, s_end_effector_pose_gradient, s_ee_arena, d_robotModel);
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_EE_COST 1
        #define GRID_PLANT_HAS_TRACKING_COST 1
        /**
         * com_cost_kernel: value + grad_x + GN hess_x per timestep
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad grad over x (14 per timestep)
         * @param d_hess dense col-major x-hessian (196 per timestep)
         * @param d_q joint positions (NUM_POS per timestep)
         * @param d_p_des desired CoM position (3 per timestep)
         * @param d_W per-axis weight (3 per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, bool MUJOCO_OUTPUT = false>
        __global__
        void com_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_p_des, const T *d_W, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
            extern __shared__ __align__(16) T s_com_arena[];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                const T *s_q = &d_q[k*7]; const T *s_p_des = &d_p_des[k*3]; const T *s_W = &d_W[k*3];
                com_cost<T>(&d_out[k], s_q, s_p_des, s_W, s_com_arena, d_robotModel);
                __syncthreads();
                com_cost_gradient<T>(&d_grad[k*14], s_q, s_p_des, s_W, s_com_arena, d_robotModel);
                __syncthreads();
                com_cost_hessian<T>(&d_hess[k*196], s_q, s_W, s_com_arena, d_robotModel);
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_COM_COST 1
        /**
         * momentum_cost_kernel: value + grad_x + GN hess_x per timestep
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad grad over x (14 per timestep)
         * @param d_hess dense col-major x-hessian (196 per timestep)
         * @param d_q / d_qd joint positions/velocities (NUM_POS / NUM_VEL per timestep)
         * @param d_h_des desired centroidal momentum (6 per timestep)
         * @param d_W per-component weight (6 per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, bool MUJOCO_OUTPUT = false>
        __global__
        void momentum_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_qd, const T *d_h_des, const T *d_W, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
            extern __shared__ __align__(16) T s_ccrba_arena[];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                const T *s_q = &d_q[k*7]; const T *s_qd = &d_qd[k*7];
                const T *s_h_des = &d_h_des[k*6]; const T *s_W = &d_W[k*6];
                momentum_cost<T>(&d_out[k], s_q, s_qd, s_h_des, s_W, s_ccrba_arena, d_robotModel);
                __syncthreads();
                momentum_cost_gradient<T>(&d_grad[k*14], s_q, s_qd, s_h_des, s_W, s_ccrba_arena, d_robotModel);
                __syncthreads();
                momentum_cost_hessian<T>(&d_hess[k*196], s_q, s_qd, s_W, s_ccrba_arena, d_robotModel);
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_MOMENTUM_COST 1
    }
